-- Question of the Day (QOTD): per-person daily question by brand + role, spaced repetition, points, Brainiac badge
create table if not exists public.qotd_questions (
  id bigserial primary key,
  brand text not null default 'all' check (brand in ('all','IHG','Hilton','Marriott')),
  role_group text not null default 'all' check (role_group in ('all','front_desk','housekeeping','maintenance','breakfast','driver','bartender','management')),
  topic text not null,
  question_en text not null check (length(trim(question_en))>0),
  question_es text not null check (length(trim(question_es))>0),
  options_en jsonb not null, options_es jsonb not null,
  correct_idx int not null,
  explain_en text not null check (length(trim(explain_en))>0),
  explain_es text not null check (length(trim(explain_es))>0),
  source_url text not null,
  es_reviewed boolean not null default true,      -- false = auto-translated draft, not served until reviewed
  active boolean not null default true, retired_at timestamptz,
  created_by uuid, updated_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(),
  check (jsonb_typeof(options_en)='array' and jsonb_array_length(options_en) between 3 and 4),
  check (jsonb_typeof(options_es)='array' and jsonb_array_length(options_es)=jsonb_array_length(options_en)),
  check (correct_idx>=0 and correct_idx<jsonb_array_length(options_en)),
  unique (brand, role_group, question_en));
create table if not exists public.qotd_daily (
  user_id uuid not null, day date not null, hotel_id text not null, question_id bigint not null references public.qotd_questions(id),
  role_group text, is_review boolean default false,
  answered_idx int, correct boolean, answered_at timestamptz,
  primary key (user_id, day));
create index if not exists qotd_daily_q on public.qotd_daily(question_id);
create table if not exists public.qotd_review (   -- spaced repetition queue for missed questions
  user_id uuid not null, question_id bigint not null references public.qotd_questions(id),
  due_date date not null, interval_days int not null default 3, misses int not null default 1,
  primary key (user_id, question_id));
alter table public.user_stats add column if not exists qotd_streak int not null default 0;
alter table public.user_stats add column if not exists qotd_best int not null default 0;
alter table public.user_stats add column if not exists qotd_last date;

on conflict do nothing;
select h.id, r.* from public.hotels h cross join (values
 ('qotd_answer','Question of the Day answered','Pregunta del día respondida',1,1,'{}'::jsonb),
 ('qotd_correct','Question of the Day correct','Pregunta del día correcta',5,1,'{"review_bonus":0}'::jsonb)) r(a,b,c,d,e,f)
on conflict (hotel_id,reason) do nothing;

create or replace function private.qotd_group(p_role text) returns text language sql immutable as $$
  select case p_role when 'front_desk' then 'front_desk' when 'night_audit' then 'front_desk'
    when 'hk_lead' then 'housekeeping' when 'housekeeper' then 'housekeeping' when 'laundry' then 'housekeeping' when 'house_person' then 'housekeeping'
    when 'maintenance' then 'maintenance' when 'breakfast' then 'breakfast' when 'shuttle_driver' then 'driver' when 'bartender' then 'bartender'
    else 'management' end $$;

-- today's question for the caller (creates it on first call). Never returns the answer.
create or replace function public.get_qotd() returns jsonb language plpgsql security definer set search_path=public,private as $$
declare u uuid := auth.uid(); h text; rl text; grp text; br text; d date := (now() at time zone 'America/Chicago')::date;
  row_ qotd_daily; qid bigint; rev boolean := false; qq qotd_questions; st user_stats;
begin
  if u is null then raise exception 'sign in'; end if;
  select p.hotel_id, p.role::text into h, rl from profiles p where p.user_id=u;
  grp := private.qotd_group(rl); select brand into br from hotels where id=h;
  select * into row_ from qotd_daily where user_id=u and day=d;
  if not found then
    -- 1) spaced-repetition review that is due
    select r.question_id into qid from qotd_review r join qotd_questions x on x.id=r.question_id and x.active
      where r.user_id=u and r.due_date<=d order by r.due_date, random() limit 1;
    rev := qid is not null;
    -- 2) unseen question for brand+role (role-specific weighted 2:1 over 'all')
    if qid is null then
      select x.id into qid from qotd_questions x where x.active and x.es_reviewed
        and x.brand in ('all',br) and x.role_group in ('all',grp)
        and not exists (select 1 from qotd_daily y where y.user_id=u and y.question_id=x.id)
        order by random() * case when x.role_group=grp then 1 else 2 end limit 1;
    end if;
    -- 3) bank exhausted: least-recently-seen
    if qid is null then
      select x.id into qid from qotd_questions x where x.active and x.es_reviewed and x.brand in ('all',br) and x.role_group in ('all',grp)
        order by (select max(day) from qotd_daily y where y.user_id=u and y.question_id=x.id) nulls first, random() limit 1;
    end if;
    if qid is null then return null; end if;
      on conflict do nothing;
    select * into row_ from qotd_daily where user_id=u and day=d;
  end if;
  select * into qq from qotd_questions where id=row_.question_id;
  select * into st from user_stats where user_id=u;
  return jsonb_build_object('day',d,'question_id',qq.id,'topic',qq.topic,'is_review',row_.is_review,
    'question_en',qq.question_en,'question_es',qq.question_es,'options_en',qq.options_en,'options_es',qq.options_es,
    'answered',row_.answered_at is not null,'answered_idx',row_.answered_idx,'correct',row_.correct,
    'correct_idx',case when row_.answered_at is not null then qq.correct_idx end,
    'explain_en',case when row_.answered_at is not null then qq.explain_en end,
    'explain_es',case when row_.answered_at is not null then qq.explain_es end,
    'source_url',case when row_.answered_at is not null then qq.source_url end,
    'streak',coalesce(st.qotd_streak,0));
end $$;

-- one attempt per day
create or replace function public.answer_qotd(p_idx int) returns jsonb language plpgsql security definer set search_path=public,private as $$
declare u uuid := auth.uid(); d date := (now() at time zone 'America/Chicago')::date; row_ qotd_daily; qq qotd_questions;
  ok boolean; pts int := 0; st user_stats; badge_before int; badge_after int;
begin
  select * into row_ from qotd_daily where user_id=u and day=d for update;
  if not found then raise exception 'no question today'; end if;
  if row_.answered_at is not null then raise exception 'already answered'; end if;
  select * into qq from qotd_questions where id=row_.question_id;
  if p_idx is null or p_idx<0 or p_idx>=jsonb_array_length(qq.options_en) then raise exception 'bad option'; end if;
  ok := p_idx=qq.correct_idx;
  update qotd_daily set answered_idx=p_idx, correct=ok, answered_at=now() where user_id=u and day=d;
  -- streak (consecutive days answered, right or wrong)
  update user_stats set qotd_streak=case when qotd_last=d-1 then qotd_streak+1 when qotd_last=d then qotd_streak else 1 end,
    qotd_last=d where user_id=u returning * into st;
  update user_stats set qotd_best=greatest(qotd_best,qotd_streak) where user_id=u;
  -- spaced repetition: miss -> due in 3 days, then 7, 14; correct on review -> doubled interval, removed after 14+
  if not ok then
      on conflict (user_id,question_id) do update set due_date=d+3, interval_days=3, misses=qotd_review.misses+1;
  elsif row_.is_review then
    update qotd_review set interval_days=interval_days*2, due_date=d+interval_days*2 where user_id=u and question_id=qq.id;
    delete from qotd_review where user_id=u and question_id=qq.id and interval_days>14;
  end if;
  select count(*) into badge_before from user_badges where user_id=u and code='brainiac';
  pts := private.award(u,row_.hotel_id,'qotd_answer','qotd',u::text||':'||d);
  if ok then pts := pts + private.award(u,row_.hotel_id,'qotd_correct','qotd',u::text||':'||d); end if;
  perform private.refresh_stats(u,row_.hotel_id);
  select count(*) into badge_after from user_badges where user_id=u and code='brainiac';
  return jsonb_build_object('correct',ok,'correct_idx',qq.correct_idx,'points',pts,'streak',st.qotd_streak,
    'explain_en',qq.explain_en,'explain_es',qq.explain_es,'source_url',qq.source_url,'new_badge',badge_after>badge_before);
end $$;

-- GM/owner question editor: requires EN + ES. p_es_draft=true marks auto-translated ES as needing review (not served).
create or replace function public.qotd_upsert(p_id bigint, p jsonb) returns bigint language plpgsql security definer set search_path=public,private as $$
declare id_ bigint;
begin
  if not (private.is_above() or private.my_role() in ('gm','agm')) then raise exception 'not allowed'; end if;
  if coalesce(p->>'source_url','')='' then raise exception 'source_url required (use "general hospitality best practice" if none)'; end if;
  if p_id is null then
    values (coalesce(p->>'brand','all'),coalesce(p->>'role_group','all'),p->>'topic',p->>'question_en',p->>'question_es',p->'options_en',p->'options_es',
      (p->>'correct_idx')::int,p->>'explain_en',p->>'explain_es',p->>'source_url',coalesce((p->>'es_reviewed')::boolean,true),auth.uid(),auth.uid()) returning id into id_;
  else
    update qotd_questions set brand=coalesce(p->>'brand',brand), role_group=coalesce(p->>'role_group',role_group), topic=coalesce(p->>'topic',topic),
      question_en=coalesce(p->>'question_en',question_en), question_es=coalesce(p->>'question_es',question_es),
      options_en=coalesce(p->'options_en',options_en), options_es=coalesce(p->'options_es',options_es),
      correct_idx=coalesce((p->>'correct_idx')::int,correct_idx), explain_en=coalesce(p->>'explain_en',explain_en), explain_es=coalesce(p->>'explain_es',explain_es),
      source_url=coalesce(p->>'source_url',source_url), es_reviewed=coalesce((p->>'es_reviewed')::boolean,es_reviewed),
      updated_by=auth.uid(), updated_at=now() where id=p_id returning id into id_;
  end if;
  return id_;
end $$;
create or replace function public.qotd_retire(p_id bigint, p_retire boolean default true) returns void language plpgsql security definer set search_path=public,private as $$
begin
  if not (private.is_above() or private.my_role() in ('gm','agm')) then raise exception 'not allowed'; end if;
  update qotd_questions set active=not p_retire, retired_at=case when p_retire then now() end, updated_by=auth.uid(), updated_at=now() where id=p_id;
end $$;

-- analytics: % correct grouped by topic | role | hotel | question, over N days
create or replace function public.qotd_analytics(p_hotel text default null, p_by text default 'topic', p_days int default 30)
returns table(grp text, answered bigint, correct bigint, pct_correct numeric) language sql security definer set search_path=public,private stable as $$
  select case p_by when 'role' then d.role_group when 'hotel' then d.hotel_id when 'question' then q.id||' · '||left(q.question_en,60) else q.topic end,
    count(*), count(*) filter (where d.correct), round(100.0*count(*) filter (where d.correct)/nullif(count(*),0),1)
  from qotd_daily d join qotd_questions q on q.id=d.question_id
  where d.answered_at is not null and d.day >= current_date-p_days
    and (p_hotel is null or d.hotel_id=p_hotel)
    and (private.is_above() or (private.is_mgr_of(d.hotel_id)))
  group by 1 order by 4 nulls last, 2 desc $$;
-- who's struggling: lowest % correct (min 5 answers) and missed-day count
create or replace function public.qotd_struggling(p_hotel text, p_days int default 30)
returns table(user_id uuid, name text, role text, answered bigint, pct_correct numeric, weakest_topic text, review_due bigint, streak int)
language sql security definer set search_path=public,private stable as $$
  select d.user_id, p.name, p.role::text, count(*), round(100.0*count(*) filter (where d.correct)/count(*),1),
    (select q2.topic from qotd_daily d2 join qotd_questions q2 on q2.id=d2.question_id where d2.user_id=d.user_id and d2.answered_at is not null
       group by q2.topic order by avg(case when d2.correct then 1 else 0 end), count(*) desc limit 1),
    (select count(*) from qotd_review r where r.user_id=d.user_id), max(s.qotd_streak)
  from qotd_daily d join profiles p on p.user_id=d.user_id left join user_stats s on s.user_id=d.user_id
  where d.hotel_id=p_hotel and d.answered_at is not null and d.day>=current_date-p_days and private.is_mgr_of(p_hotel)
  group by d.user_id,p.name,p.role having count(*)>=5 order by 5 asc limit 50 $$;

alter table public.qotd_questions enable row level security; alter table public.qotd_daily enable row level security; alter table public.qotd_review enable row level security;
-- staff never read the bank directly (would expose answers); managers can
create policy qotd_q_mgr_read on public.qotd_questions for select using (private.is_above() or private.my_role() in ('gm','agm'));
create policy qotd_daily_read on public.qotd_daily for select using (private.is_mgr_of(hotel_id));
create policy qotd_review_read on public.qotd_review for select using (user_id=auth.uid());
revoke execute on function public.get_qotd, public.answer_qotd, public.qotd_upsert, public.qotd_retire, public.qotd_analytics, public.qotd_struggling from anon;
on conflict (brand,role_group,question_en) do nothing;
