    insert into qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,es_reviewed,created_by,updated_by)
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url) values
('IHG','front_desk','loyalty','What is the base (entry) tier of IHG One Rewards?','¿Cuál es el nivel inicial de IHG One Rewards?','["Silver Elite", "Gold Elite", "Club Member"]'::jsonb,'["Silver Elite", "Gold Elite", "Club Member"]'::jsonb,2,'Every new member starts at Club. Elite tiers begin at Silver.','Todo socio nuevo empieza en Club. Los niveles Elite comienzan en Silver.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','How many qualifying nights in a year earn IHG Silver Elite?','¿Cuántas noches calificadas al año se necesitan para Silver Elite de IHG?','["40", "5", "10", "20"]'::jsonb,'["40", "5", "10", "20"]'::jsonb,2,'Silver Elite takes 10 qualifying nights in a calendar year.','Silver Elite requiere 10 noches calificadas en un año calendario.','https://www.ihg.com/content/us/en/customer-care/member-tc'),
('IHG','front_desk','loyalty','Which IHG One Rewards perk can you promise every member, even Club?','¿Qué beneficio de IHG One Rewards puedes ofrecer a todo socio, incluso Club?','["Guaranteed suite upgrade", "Free breakfast welcome amenity", "Free internet and member rates"]'::jsonb,'["Mejora garantizada a suite", "Desayuno gratis de bienvenida", "Internet gratis y tarifas para socios"]'::jsonb,2,'Free internet and member rates are included at every tier. Upgrades and amenities start at Platinum.','El internet gratis y las tarifas para socios se incluyen en todos los niveles. Las mejoras y amenidades empiezan en Platinum.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Which IHG tier earns a 100% points bonus?','¿Qué nivel de IHG gana un bono del 100% en puntos?','["Platinum Elite", "Diamond Elite", "Gold Elite"]'::jsonb,'["Platinum Elite", "Diamond Elite", "Gold Elite"]'::jsonb,1,'Diamond earns 100%. Silver 20%, Gold 40%, Platinum 60%.','Diamond gana 100%. Silver 20%, Gold 40%, Platinum 60%.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','For IHG members, when do points stop expiring?','Para socios de IHG, ¿cuándo dejan de vencer los puntos?','["Starting at Silver Elite", "Never—they always expire", "Only at Diamond Elite"]'::jsonb,'["A partir de Silver Elite", "Nunca, siempre vencen", "Solo en Diamond Elite"]'::jsonb,0,'Points don''t expire for Silver Elite and above.','Los puntos no vencen para Silver Elite en adelante.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','An IHG Platinum Elite guest arrives. Which benefit may they choose at check-in?','Llega un huésped Platinum Elite de IHG. ¿Qué beneficio puede elegir al registrarse?','["Free parking for life", "A welcome amenity (points or drink/snack)", "A free night"]'::jsonb,'["Estacionamiento gratis de por vida", "Una amenidad de bienvenida (puntos o bebida/snack)", "Una noche gratis"]'::jsonb,1,'Platinum and Diamond get a welcome amenity. Diamond can also choose breakfast.','Platinum y Diamond reciben una amenidad de bienvenida. Diamond también puede elegir desayuno.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Late checkout for IHG One Rewards members is up to what time, subject to availability?','¿Hasta qué hora es la salida tardía para socios de IHG One Rewards, según disponibilidad?','["4 PM", "2 PM", "12 PM"]'::jsonb,'["4 p. m.", "2 p. m.", "12 p. m."]'::jsonb,1,'All tiers can request late checkout up to 2 PM when available.','Todos los niveles pueden pedir salida tardía hasta las 2 p. m. si hay disponibilidad.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','A guest booked through a third-party site and asks to join IHG. Best response?','Un huésped reservó por un sitio externo y quiere unirse a IHG. ¿Mejor respuesta?','["Tell them they can''t join", "Change their rate to a member rate", "Enroll them now and explain booking direct next time gets member rates"]'::jsonb,'["Dile que no puede unirse", "Cámbiale la tarifa a la de socio", "Inscríbelo ahora y explícale que reservando directo la próxima vez obtiene tarifas de socio"]'::jsonb,2,'Always enroll. Member rates apply when booking direct; don''t alter a third-party rate.','Siempre inscribe. Las tarifas de socio aplican al reservar directo; no cambies una tarifa de terceros.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Which IHG tier first gets reward-night discounts?','¿Qué nivel de IHG obtiene primero descuentos en noches de recompensa?','["Platinum Elite", "Silver Elite", "Gold Elite"]'::jsonb,'["Platinum Elite", "Silver Elite", "Gold Elite"]'::jsonb,0,'Reward Night Discounts start at Platinum Elite.','Los descuentos en noches de recompensa empiezan en Platinum Elite.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','IHG Platinum and Diamond members get guaranteed room availability when booking how far ahead?','¿Con cuánta anticipación tienen disponibilidad garantizada los socios Platinum y Diamond de IHG?','["72 hours", "48 hours", "24 hours"]'::jsonb,'["72 horas", "48 horas", "24 horas"]'::jsonb,0,'Platinum and Diamond: guaranteed availability with 72 hours'' notice.','Platinum y Diamond: disponibilidad garantizada con 72 horas de aviso.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Which is a good 10-second IHG enrollment pitch?','¿Cuál es un buen discurso de 10 segundos para inscribir en IHG?','["You have to join to stay here", "It costs $10 but pays off", "It''s free, you get free Wi-Fi and member rates, and points toward free nights"]'::jsonb,'["Tiene que unirse para hospedarse aquí", "Cuesta $10 pero vale la pena", "Es gratis, tiene Wi-Fi gratis, tarifas de socio y puntos para noches gratis"]'::jsonb,2,'Keep it short, free, and benefit-focused. Joining is never required to stay.','Hazlo corto, gratis y enfocado en beneficios. Nunca es obligatorio unirse para hospedarse.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Do IHG reward nights have blackout dates?','¿Las noches de recompensa de IHG tienen fechas bloqueadas?','["Only on weekends", "No blackout dates", "Yes, on holidays"]'::jsonb,'["Solo los fines de semana", "No hay fechas bloqueadas", "Sí, en días festivos"]'::jsonb,1,'IHG lists ''No Blackout Dates for Reward Nights'' for all tiers.','IHG indica ''sin fechas bloqueadas para noches de recompensa'' en todos los niveles.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','front_desk','loyalty','Which IHG tier begins rolling over extra qualifying nights to next year?','¿Desde qué nivel de IHG se transfieren las noches extra al año siguiente?','["Silver Elite", "Diamond only", "Gold Elite"]'::jsonb,'["Silver Elite", "Solo Diamond", "Gold Elite"]'::jsonb,2,'Rollover Nights start at Gold Elite.','Las noches transferibles empiezan en Gold Elite.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','all','loyalty','A guest mentions they travel a lot but aren''t an IHG member. What do you do if you''re not at the desk?','Un huésped dice que viaja mucho pero no es socio de IHG. ¿Qué haces si no estás en recepción?','["Mention it''s free and send them to the front desk to enroll", "Sign them up with your own email", "Ignore it—not your job"]'::jsonb,'["Menciona que es gratis y envíalo a recepción para inscribirse", "Inscríbelo con tu propio correo", "Ignóralo, no es tu trabajo"]'::jsonb,0,'Everyone can help with enrollments. Never use your own information for a guest account.','Todos pueden ayudar con las inscripciones. Nunca uses tus datos para la cuenta de un huésped.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','all','loyalty','What is IHG''s loyalty program called?','¿Cómo se llama el programa de lealtad de IHG?','["IHG One Rewards", "Priority Club Bonvoy", "IHG Honors"]'::jsonb,'["IHG One Rewards", "Priority Club Bonvoy", "IHG Honors"]'::jsonb,0,'It''s IHG One Rewards.','Se llama IHG One Rewards.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','all','loyalty','Which IHG tier comes right after Gold Elite?','¿Qué nivel de IHG sigue después de Gold Elite?','["Diamond Elite", "Platinum Elite", "Silver Elite"]'::jsonb,'["Diamond Elite", "Platinum Elite", "Silver Elite"]'::jsonb,1,'Club → Silver → Gold → Platinum → Diamond.','Club → Silver → Gold → Platinum → Diamond.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','housekeeping','loyalty','An IHG Platinum guest may get an early check-in. What helps most?','Un huésped Platinum de IHG podría tener entrada anticipada. ¿Qué ayuda más?','["Skip inspection to go faster", "Clean rooms strictly in number order", "Clean flagged early-arrival rooms first when the desk asks"]'::jsonb,'["Saltar la inspección para ir más rápido", "Limpiar estrictamente en orden numérico", "Limpiar primero las habitaciones marcadas para llegada anticipada cuando recepción lo pida"]'::jsonb,2,'Early check-in for Platinum/Diamond is subject to availability—priority rooms make it possible.','La entrada anticipada para Platinum/Diamond depende de disponibilidad; las habitaciones prioritarias la hacen posible.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','management','loyalty','How many qualifying nights earn IHG Diamond Elite?','¿Cuántas noches calificadas se necesitan para Diamond Elite de IHG?','["100", "70", "50"]'::jsonb,'["100", "70", "50"]'::jsonb,1,'Diamond: 70 nights or 120,000 qualifying points.','Diamond: 70 noches o 120,000 puntos calificados.','https://www.ihg.com/content/us/en/customer-care/member-tc'),
('IHG','management','loyalty','IHG Gold Elite can be earned with 20 nights or how many qualifying points?','Gold Elite de IHG se obtiene con 20 noches o ¿cuántos puntos calificados?','["20,000", "40,000", "60,000"]'::jsonb,'["20,000", "40,000", "60,000"]'::jsonb,1,'Gold: 20 nights or 40,000 qualifying points.','Gold: 20 noches o 40,000 puntos calificados.','https://www.ihg.com/content/us/en/customer-care/member-tc'),
('IHG','management','loyalty','Which Hertz status comes with IHG Diamond Elite?','¿Qué estatus de Hertz incluye Diamond Elite de IHG?','["None", "President''s Circle", "Five Star"]'::jsonb,'["Ninguno", "President''s Circle", "Five Star"]'::jsonb,1,'Gold/Platinum get Five Star; Diamond gets President''s Circle.','Gold/Platinum reciben Five Star; Diamond recibe President''s Circle.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','breakfast','loyalty','Which IHG tier can pick free breakfast as a welcome amenity?','¿Qué nivel de IHG puede elegir desayuno gratis como amenidad de bienvenida?','["Platinum Elite", "Diamond Elite", "Gold Elite"]'::jsonb,'["Platinum Elite", "Diamond Elite", "Gold Elite"]'::jsonb,1,'Only Diamond lists breakfast as a welcome amenity option.','Solo Diamond incluye desayuno como opción de amenidad.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','maintenance','loyalty','Complimentary upgrades at IHG start at which tier (subject to availability)?','¿Desde qué nivel de IHG hay mejoras de habitación gratis (según disponibilidad)?','["Silver Elite", "Club Member", "Platinum Elite"]'::jsonb,'["Silver Elite", "Club Member", "Platinum Elite"]'::jsonb,2,'Upgrades start at Platinum—so out-of-order rooms limit them. Fix and return rooms fast.','Las mejoras empiezan en Platinum; las habitaciones fuera de servicio las limitan. Repáralas rápido.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('Hilton','all','brand_service','What does the 100% Hampton Guarantee ask team members to do when a guest has an issue?','¿Qué pide la Garantía 100% Hampton cuando un huésped tiene un problema?','["Refer them to corporate", "Make It Right", "Offer points only"]'::jsonb,'["Enviarlo a corporativo", "Resolverlo (Make It Right)", "Ofrecer solo puntos"]'::jsonb,1,'Hampton''s promise: talk to any team member and we''ll Make It Right.','La promesa de Hampton: hable con cualquier miembro del equipo y lo resolveremos.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','all','brand_service','Who can act on the Hampton Guarantee?','¿Quién puede actuar bajo la Garantía Hampton?','["Any team member the guest talks to", "Only front desk", "Only the GM"]'::jsonb,'["Cualquier miembro del equipo con quien hable el huésped", "Solo recepción", "Solo el gerente general"]'::jsonb,0,'The brand says talk to ANY team member. Own it, then loop in a manager if needed.','La marca dice que hable con CUALQUIER miembro del equipo. Hazte cargo y avisa a un gerente si hace falta.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','breakfast','brand_service','Which item is Hampton''s signature at free hot breakfast?','¿Cuál es el producto emblemático del desayuno caliente gratis de Hampton?','["Waffles", "Pancakes", "Omelet station"]'::jsonb,'["Waffles", "Panqueques", "Estación de omelets"]'::jsonb,0,'Hampton highlights free hot breakfast with waffles.','Hampton destaca su desayuno caliente gratis con waffles.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','front_desk','loyalty','What are Hilton Honors'' five tiers?','¿Cuáles son los cinco niveles de Hilton Honors?','["Member, Gold, Platinum, Titanium, Ambassador", "Club, Silver, Gold, Platinum, Diamond", "Member, Silver, Gold, Diamond, Diamond Reserve"]'::jsonb,'["Member, Gold, Platinum, Titanium, Ambassador", "Club, Silver, Gold, Platinum, Diamond", "Member, Silver, Gold, Diamond, Diamond Reserve"]'::jsonb,2,'Hilton: Member, Silver, Gold, Diamond, Diamond Reserve.','Hilton: Member, Silver, Gold, Diamond, Diamond Reserve.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Silver status in Hilton Honors needs 10 nights, $2,500 spend, or how many stays?','El estatus Silver de Hilton Honors requiere 10 noches, $2,500 de gasto o ¿cuántas estancias?','["8", "2", "4"]'::jsonb,'["8", "2", "4"]'::jsonb,2,'Silver: 10 nights, 4 stays, or $2,500 eligible spend.','Silver: 10 noches, 4 estancias o $2,500 de gasto elegible.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Which is a Member-level Hilton Honors benefit when booking direct?','¿Cuál es un beneficio de nivel Member de Hilton Honors al reservar directo?','["Executive lounge", "48-hour room guarantee", "Choose your own room and Digital Key"]'::jsonb,'["Sala ejecutiva", "Garantía de habitación de 48 horas", "Elegir su habitación y Llave Digital"]'::jsonb,2,'All members get free Wi-Fi, choose-your-room, and Digital Key when booking direct.','Todos los socios tienen Wi-Fi gratis, elegir habitación y Llave Digital al reservar directo.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Hilton''s Fifth Night Free applies to what kind of stay?','¿A qué tipo de estancia aplica la Quinta Noche Gratis de Hilton?','["All-points Standard Room Reward stays of 5+ nights for Silver and up", "Points & Money stays", "Any paid stay of 5 nights"]'::jsonb,'["Estancias de recompensa en habitación estándar, solo con puntos, de 5+ noches para Silver en adelante", "Estancias de Puntos y Dinero", "Cualquier estancia pagada de 5 noches"]'::jsonb,0,'Elite members only, all-points standard room rewards, 5+ nights. Not paid or Points & Money stays.','Solo socios Elite, recompensas en habitación estándar con todos los puntos, 5+ noches. No aplica a estancias pagadas ni Puntos y Dinero.','https://www.hilton.com/en/hilton-honors/support-faq/'),
('Hilton','front_desk','loyalty','What points bonus do Hilton Honors Gold members earn on stays?','¿Qué bono de puntos ganan los socios Gold de Hilton Honors?','["20%", "50%", "80%"]'::jsonb,'["20%", "50%", "80%"]'::jsonb,2,'Silver 20%, Gold 80%, Diamond 100%, Diamond Reserve 120%.','Silver 20%, Gold 80%, Diamond 100%, Diamond Reserve 120%.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','At U.S. hotels, Hilton Gold members get which daily benefit?','En hoteles de EE. UU., ¿qué beneficio diario reciben los socios Gold de Hilton?','["Free parking", "Food and beverage credit", "Free laundry"]'::jsonb,'["Estacionamiento gratis", "Crédito de alimentos y bebidas", "Lavandería gratis"]'::jsonb,1,'Gold: Daily Food & Beverage Credit at U.S. hotels.','Gold: crédito diario de alimentos y bebidas en hoteles de EE. UU.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','A Gold member asks for an upgrade. What''s accurate?','Un socio Gold pide una mejora. ¿Qué es correcto?','["Space-available upgrades—offer one if a better room is open", "Upgrades are guaranteed", "Gold members never get upgrades"]'::jsonb,'["Mejoras según disponibilidad; ofrécela si hay una mejor habitación libre", "Las mejoras están garantizadas", "Los Gold nunca reciben mejoras"]'::jsonb,0,'Gold and up get space-available upgrades.','Gold en adelante recibe mejoras según disponibilidad.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Which tier gets a 48-hour room guarantee?','¿Qué nivel tiene garantía de habitación de 48 horas?','["Diamond", "Gold", "Silver"]'::jsonb,'["Diamond", "Gold", "Silver"]'::jsonb,0,'Diamond (and Diamond Reserve) get the 48-hour room guarantee.','Diamond (y Diamond Reserve) tienen la garantía de 48 horas.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Do Hilton Honors points earned count toward elite tier status?','¿Los puntos ganados en Hilton Honors cuentan para el estatus Elite?','["Only on weekends", "No—nights, stays, or eligible spend count", "Yes, always"]'::jsonb,'["Solo los fines de semana", "No; cuentan noches, estancias o gasto elegible", "Sí, siempre"]'::jsonb,1,'Hilton terms: points earned do not count toward tier qualification.','Según Hilton, los puntos ganados no cuentan para calificar de nivel.','https://www.hilton.com/en/hilton-honors/terms'),
('Hilton','front_desk','loyalty','Best short Hilton Honors enrollment pitch?','¿Mejor discurso corto para inscribir en Hilton Honors?','["Required for all guests", "Only worth it for Diamond travelers", "Free to join—free Wi-Fi, choose your room, Digital Key, and points toward free nights"]'::jsonb,'["Obligatorio para todos", "Solo vale la pena para viajeros Diamond", "Es gratis: Wi-Fi gratis, elige tu habitación, Llave Digital y puntos para noches gratis"]'::jsonb,2,'Lead with free plus everyday perks.','Empieza con que es gratis y los beneficios del día a día.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','front_desk','loyalty','Diamond status in Hilton Honors needs 25 stays, $11,500 spend, or how many nights?','El estatus Diamond requiere 25 estancias, $11,500 o ¿cuántas noches?','["50", "60", "40"]'::jsonb,'["50", "60", "40"]'::jsonb,0,'Diamond: 50 nights, 25 stays, or $11,500.','Diamond: 50 noches, 25 estancias o $11,500.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','all','loyalty','Which loyalty program goes with Hampton Inn?','¿Qué programa de lealtad corresponde a Hampton Inn?','["Marriott Bonvoy", "Hilton Honors", "IHG One Rewards"]'::jsonb,'["Marriott Bonvoy", "Hilton Honors", "IHG One Rewards"]'::jsonb,1,'Hampton is a Hilton brand.','Hampton es una marca de Hilton.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','housekeeping','brand_service','A guest says the room wasn''t clean. Under the Hampton Guarantee you should:','Un huésped dice que la habitación no estaba limpia. Según la Garantía Hampton debes:','["Apologize, fix it now, and tell your supervisor", "Say it was cleaned and leave", "Tell them to call corporate"]'::jsonb,'["Disculparte, arreglarlo de inmediato y avisar a tu supervisor", "Decir que ya se limpió e irte", "Decirle que llame a corporativo"]'::jsonb,0,'Clean rooms are part of the guarantee. Own it and Make It Right.','Las habitaciones limpias son parte de la garantía. Hazte cargo y resuélvelo.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','maintenance','brand_service','A guest reports a broken AC at 9 PM. Hampton Guarantee mindset says:','Un huésped reporta el aire acondicionado roto a las 9 p. m. Según la Garantía Hampton:','["Wait for morning", "Tell them it''s normal", "Fix it or move them quickly, and follow up"]'::jsonb,'["Esperar a la mañana", "Decirle que es normal", "Repararlo o cambiarlo de habitación rápido y dar seguimiento"]'::jsonb,2,'Comfortable surroundings are part of the promise—act fast and follow up.','El confort es parte de la promesa: actúa rápido y da seguimiento.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','driver','brand_service','A shuttle guest is unhappy about a late pickup. Hampton approach?','Un huésped del shuttle está molesto por una recogida tardía. ¿Enfoque Hampton?','["Say nothing", "Apologize, own it, and tell the desk so they can Make It Right", "Blame traffic and move on"]'::jsonb,'["No decir nada", "Disculparte, hacerte cargo y avisar a recepción para resolverlo", "Culpar al tráfico y seguir"]'::jsonb,1,'Any team member can start Make It Right.','Cualquier miembro del equipo puede iniciar la solución.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Hilton','management','loyalty','Diamond Reserve requires 80 nights or 40 stays AND what annual spend?','Diamond Reserve requiere 80 noches o 40 estancias Y ¿qué gasto anual?','["$23,000", "$18,000", "$11,500"]'::jsonb,'["$23,000", "$18,000", "$11,500"]'::jsonb,1,'Diamond Reserve: 80 nights or 40 stays plus $18,000 eligible spend.','Diamond Reserve: 80 noches o 40 estancias más $18,000 de gasto elegible.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','management','loyalty','Which Hilton tier first gets Milestone Bonuses?','¿Qué nivel de Hilton obtiene primero los Milestone Bonuses?','["Gold", "Silver", "Diamond"]'::jsonb,'["Gold", "Silver", "Diamond"]'::jsonb,0,'Milestone Bonuses are listed under Gold.','Los Milestone Bonuses aparecen en el nivel Gold.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Hilton','breakfast','brand_service','Breakfast is running low on waffle batter with guests waiting. Best move?','Se está acabando la mezcla de waffles y hay huéspedes esperando. ¿Mejor acción?','["Put out a ''sold out'' sign", "Close breakfast early", "Restock right away and tell guests it''s coming"]'::jsonb,'["Poner un letrero de ''agotado''", "Cerrar el desayuno temprano", "Reponer de inmediato y avisar a los huéspedes que ya viene"]'::jsonb,2,'Signature items should stay available; keep guests informed.','Los productos emblemáticos deben estar disponibles; mantén informados a los huéspedes.','https://www.hilton.com/en/brands/hampton-by-hilton/'),
('Marriott','front_desk','loyalty','Marriott Bonvoy Silver Elite takes how many nights per year?','¿Cuántas noches al año requiere Silver Elite de Marriott Bonvoy?','["15", "25", "10"]'::jsonb,'["15", "25", "10"]'::jsonb,2,'Silver 10, Gold 25, Platinum 50, Titanium 75.','Silver 10, Gold 25, Platinum 50, Titanium 75.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','Which Marriott Bonvoy benefit does every member get?','¿Qué beneficio de Marriott Bonvoy recibe todo socio?','["Member rates, free in-room Wi-Fi, mobile check-in", "Lounge access", "Suite upgrade"]'::jsonb,'["Tarifas de socio, Wi-Fi gratis en la habitación y check-in móvil", "Acceso a sala", "Mejora a suite"]'::jsonb,0,'Members get member rates, free Wi-Fi when booking direct, and mobile check-in/key.','Los socios tienen tarifas de socio, Wi-Fi gratis al reservar directo y check-in/llave móvil.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','How many base points per US$ do members earn at SpringHill Suites?','¿Cuántos puntos base por dólar ganan los socios en SpringHill Suites?','["15", "10", "5"]'::jsonb,'["15", "10", "5"]'::jsonb,1,'10 base points per $1 at most brands incl. SpringHill (5 at brands like Residence Inn).','10 puntos base por $1 en la mayoría de marcas, incluida SpringHill (5 en marcas como Residence Inn).','https://www.marriott.com/loyalty/terms/default.mi'),
('Marriott','front_desk','loyalty','Gold Elite late checkout is up to what time, subject to availability?','¿Hasta qué hora es la salida tardía de Gold Elite, según disponibilidad?','["4 PM", "12 PM", "2 PM"]'::jsonb,'["4 p. m.", "12 p. m.", "2 p. m."]'::jsonb,2,'Gold Elite: 2 PM late checkout subject to availability.','Gold Elite: salida tardía hasta las 2 p. m. según disponibilidad.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','A Platinum Elite guest checks in. What do you offer?','Un huésped Platinum Elite se registra. ¿Qué le ofreces?','["Nothing extra", "A free night", "Welcome Gift choice (points, breakfast offering, or amenity—varies by brand)"]'::jsonb,'["Nada extra", "Una noche gratis", "Elegir un regalo de bienvenida (puntos, desayuno o amenidad, según la marca)"]'::jsonb,2,'Platinum and up choose a Welcome Gift; options vary by brand.','Platinum en adelante elige un regalo de bienvenida; varía según la marca.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','What bonus do Silver Elite members earn on eligible spend?','¿Qué bono ganan los socios Silver Elite en gastos elegibles?','["10%", "50%", "25%"]'::jsonb,'["10%", "50%", "25%"]'::jsonb,0,'Silver 10%, Gold 25%, Platinum 50%, Titanium/Ambassador 75%.','Silver 10%, Gold 25%, Platinum 50%, Titanium/Ambassador 75%.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','Which comes after Platinum Elite in Marriott Bonvoy?','¿Qué nivel sigue después de Platinum Elite en Marriott Bonvoy?','["Gold Elite", "Titanium Elite", "Diamond"]'::jsonb,'["Gold Elite", "Titanium Elite", "Diamond"]'::jsonb,1,'Member → Silver → Gold → Platinum → Titanium → Ambassador.','Member → Silver → Gold → Platinum → Titanium → Ambassador.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','What is ''Your24'' for Ambassador Elite?','¿Qué es ''Your24'' para Ambassador Elite?','["24% bonus points", "24-hour room service", "Choose the 24 hours of your stay"]'::jsonb,'["24% de puntos extra", "Servicio a la habitación 24 horas", "Elegir las 24 horas de su estancia"]'::jsonb,2,'Your24 lets Ambassadors pick their check-in hour and keep the room 24 hours.','Your24 permite elegir la hora de entrada y quedarse 24 horas.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','Do group or third-party bookings usually earn Marriott Bonvoy points on room rate?','¿Las reservas de grupo o de terceros suelen ganar puntos Bonvoy por la tarifa?','["Always", "Only on Fridays", "Generally only Qualifying Rates earn; many third-party rates don''t"]'::jsonb,'["Siempre", "Solo los viernes", "En general solo las tarifas calificadas ganan; muchas de terceros no"]'::jsonb,2,'Check the rate. Book direct next time for member rates and points.','Revisa la tarifa. Reservar directo la próxima vez da tarifas y puntos de socio.','https://www.marriott.com/loyalty/terms/default.mi'),
('Marriott','front_desk','loyalty','Best short Marriott Bonvoy enrollment pitch?','¿Mejor discurso corto para inscribir en Marriott Bonvoy?','["Costs a fee", "Required to check in", "Free to join—member rates, free Wi-Fi, mobile key, and points toward free nights"]'::jsonb,'["Tiene un costo", "Obligatorio para registrarse", "Es gratis: tarifas de socio, Wi-Fi gratis, llave móvil y puntos para noches gratis"]'::jsonb,2,'Free and useful on this very stay.','Gratis y útil desde esta misma estancia.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','Ambassador Elite requires 100 nights and what qualifying spend?','Ambassador Elite requiere 100 noches y ¿qué gasto calificado?','["$10,000", "$23,000", "$18,000"]'::jsonb,'["$10,000", "$23,000", "$18,000"]'::jsonb,1,'100+ nights plus $23,000+ qualifying spend.','100+ noches más $23,000+ de gasto calificado.','https://www.marriott.com/loyalty.mi'),
('Marriott','front_desk','loyalty','Can a Marriott Bonvoy member use their phone as a room key?','¿Puede un socio Bonvoy usar su teléfono como llave?','["No", "Only Titanium", "Yes, via the app (mobile key)"]'::jsonb,'["No", "Solo Titanium", "Sí, con la app (llave móvil)"]'::jsonb,2,'Mobile check-in and mobile key are member-level benefits.','El check-in y la llave móvil son beneficios de nivel Member.','https://www.marriott.com/loyalty.mi'),
('Marriott','all','loyalty','What loyalty program goes with SpringHill Suites?','¿Qué programa de lealtad corresponde a SpringHill Suites?','["Hilton Honors", "IHG One Rewards", "Marriott Bonvoy"]'::jsonb,'["Hilton Honors", "IHG One Rewards", "Marriott Bonvoy"]'::jsonb,2,'SpringHill Suites is a Marriott brand.','SpringHill Suites es una marca de Marriott.','https://www.marriott.com/loyalty.mi'),
('Marriott','all','loyalty','Which Marriott tier is 0–9 nights per year?','¿Qué nivel de Marriott es de 0 a 9 noches al año?','["Gold Elite", "Silver Elite", "Member"]'::jsonb,'["Gold Elite", "Silver Elite", "Member"]'::jsonb,2,'Member is 0–9 nights; Silver starts at 10.','Member es de 0 a 9 noches; Silver empieza en 10.','https://www.marriott.com/loyalty.mi'),
('Marriott','housekeeping','loyalty','Gold+ Bonvoy members can get 2 PM late checkout. What should housekeeping do?','Los socios Gold+ de Bonvoy pueden tener salida a las 2 p. m. ¿Qué debe hacer limpieza?','["Check the late-checkout list and don''t knock early on those rooms", "Ignore the list", "Knock at 11 AM anyway"]'::jsonb,'["Revisar la lista de salidas tardías y no tocar temprano en esas habitaciones", "Ignorar la lista", "Tocar a las 11 a. m. de todos modos"]'::jsonb,0,'Respecting approved late checkouts protects the guest experience.','Respetar las salidas tardías aprobadas cuida la experiencia del huésped.','https://www.marriott.com/loyalty.mi'),
('Marriott','bartender','loyalty','A guest at the bar asks if their tab can earn Bonvoy points. Best answer?','Un huésped en el bar pregunta si su cuenta gana puntos Bonvoy. ¿Mejor respuesta?','["Charging eligible purchases to the room can earn points—let me post it to your room", "Bar purchases never earn", "Only cash earns points"]'::jsonb,'["Cargar compras elegibles a la habitación puede ganar puntos; puedo cargarlo a su habitación", "El bar nunca gana puntos", "Solo el efectivo gana puntos"]'::jsonb,0,'Marriott says incidentals charged to the room, like dining, can earn points.','Marriott dice que los consumos cargados a la habitación, como alimentos y bebidas, pueden ganar puntos.','https://www.marriott.com/loyalty.mi'),
('Marriott','management','loyalty','Platinum Elite earns what percentage of extra points?','¿Qué porcentaje de puntos extra gana Platinum Elite?','["75%", "50%", "25%"]'::jsonb,'["75%", "50%", "25%"]'::jsonb,1,'Platinum 50%.','Platinum 50%.','https://www.marriott.com/loyalty.mi'),
('Marriott','management','loyalty','Which Marriott tier first gets ''Enhanced Room Upgrade''?','¿Qué nivel de Marriott obtiene primero la ''mejora de habitación''?','["Titanium only", "Gold Elite", "Silver Elite"]'::jsonb,'["Solo Titanium", "Gold Elite", "Silver Elite"]'::jsonb,1,'Gold lists Enhanced Room Upgrade; Platinum+ adds select suites.','Gold incluye la mejora; Platinum en adelante incluye suites selectas.','https://www.marriott.com/loyalty.mi'),
('Marriott','breakfast','loyalty','A Platinum guest picked breakfast as their Welcome Gift. Breakfast team should:','Un huésped Platinum eligió desayuno como regalo de bienvenida. El equipo de desayuno debe:','["Honor it per the front desk''s note", "Ask for proof of status", "Charge them"]'::jsonb,'["Respetarlo según la nota de recepción", "Pedirle prueba de estatus", "Cobrarle"]'::jsonb,0,'Breakfast offering is a Welcome Gift option for Platinum+; coordinate with the desk.','El desayuno es una opción de regalo para Platinum+; coordina con recepción.','https://www.marriott.com/loyalty.mi'),
('Marriott','maintenance','loyalty','Titanium members may get upgrades to Select Suites. Why do quick room repairs matter?','Los Titanium pueden recibir mejoras a suites selectas. ¿Por qué importa reparar rápido?','["Suites are never used", "More rooms available means more upgrades and happier elites", "It doesn''t matter"]'::jsonb,'["Las suites nunca se usan", "Más habitaciones disponibles significa más mejoras y Elites más contentos", "No importa"]'::jsonb,1,'Out-of-order rooms limit upgrades and sellable inventory.','Las habitaciones fuera de servicio limitan mejoras e inventario.','https://www.marriott.com/loyalty.mi'),
('Marriott','driver','loyalty','A shuttle guest asks how to get free Wi-Fi at the hotel. You say:','Un huésped en el shuttle pregunta cómo tener Wi-Fi gratis. Dices:','["Ask a manager", "Wi-Fi costs extra for everyone", "Join Marriott Bonvoy free—members get free in-room Wi-Fi when booking direct"]'::jsonb,'["Pregunte a un gerente", "El Wi-Fi cuesta para todos", "Únase gratis a Marriott Bonvoy; los socios tienen Wi-Fi gratis al reservar directo"]'::jsonb,2,'A natural enrollment moment—point them to the desk.','Un buen momento para inscribir; envíalo a recepción.','https://www.marriott.com/loyalty.mi'),
('all','all','safety','What is an SDS?','¿Qué es una SDS (hoja de datos de seguridad)?','["A staff schedule", "A sheet with a chemical''s hazards and safe handling", "A guest survey"]'::jsonb,'["Un horario del personal", "Una hoja con los peligros y manejo seguro de un químico", "Una encuesta"]'::jsonb,1,'Safety Data Sheets explain hazards, PPE, and first aid. Know where they''re kept.','Las hojas SDS explican peligros, equipo de protección y primeros auxilios. Sabe dónde están.','https://www.osha.gov/hazcom'),
('all','all','safety','Before using a new chemical you should:','Antes de usar un químico nuevo debes:','["Mix it with bleach to make it stronger", "Read the label and SDS and wear the listed PPE", "Smell it to check"]'::jsonb,'["Mezclarlo con cloro para que sea más fuerte", "Leer la etiqueta y la SDS y usar el equipo indicado", "Olerlo para revisarlo"]'::jsonb,1,'Labels and SDS tell you how to use it safely. Never mix chemicals.','La etiqueta y la SDS indican cómo usarlo seguro. Nunca mezcles químicos.','https://www.osha.gov/hazcom'),
('all','all','safety','Why should you never mix bleach and ammonia cleaners?','¿Por qué nunca se debe mezclar cloro con amoníaco?','["They release toxic gas", "It stains", "It makes them weaker"]'::jsonb,'["Liberan un gas tóxico", "Mancha", "Se debilitan"]'::jsonb,0,'Mixing creates toxic chloramine gas.','La mezcla produce gas tóxico (cloramina).','https://www.osha.gov/hazcom'),
('all','all','safety','You find a used needle. What do you do?','Encuentras una aguja usada. ¿Qué haces?','["Recap it", "Pick it up and throw it in the trash", "Don''t touch it; tell a supervisor to use a sharps container with tools"]'::jsonb,'["Ponerle la tapa", "Recogerla y tirarla a la basura", "No la toques; avisa al supervisor para usar pinzas y un contenedor para objetos punzantes"]'::jsonb,2,'Treat sharps as infectious. Use tools and a sharps container—never bare hands.','Trata los objetos punzantes como infecciosos. Usa herramientas y contenedor, nunca las manos.','https://www.osha.gov/bloodborne-pathogens'),
('all','all','safety','What''s the correct way to lift a heavy box?','¿Cuál es la forma correcta de levantar una caja pesada?','["Bend at the waist", "Bend knees, keep it close, lift with legs, don''t twist", "Lift fast and twist"]'::jsonb,'["Doblarse por la cintura", "Doblar rodillas, mantenerla cerca, levantar con las piernas, sin girar", "Levantar rápido y girar"]'::jsonb,1,'Keep the load close and avoid twisting; get help or a cart for heavy loads.','Mantén la carga cerca y no gires; pide ayuda o usa un carrito si pesa mucho.','https://www.cdc.gov/niosh/ergonomics/index.html'),
('all','all','safety','You see a spill in the lobby. First step?','Ves un derrame en el lobby. ¿Primer paso?','["Cover it with paper", "Stay with it or put a wet-floor sign, then clean it", "Walk away and report later"]'::jsonb,'["Taparlo con papel", "Quedarte ahí o poner un letrero de piso mojado y luego limpiarlo", "Irte y reportarlo después"]'::jsonb,1,'Slips are a top injury. Guard it and clean it right away.','Los resbalones son una lesión común. Señalízalo y límpialo de inmediato.','https://www.osha.gov/walking-working-surfaces'),
('all','all','emergency','Fire extinguisher method ''PASS'' stands for:','El método ''PASS'' del extintor significa:','["Pull, Aim, Squeeze, Sweep", "Pull, Alert, Spray, Save", "Push, Alarm, Spray, Stop"]'::jsonb,'["Jalar, Apuntar, Apretar, Barrer", "Jalar, Alertar, Rociar, Salvar", "Empujar, Alarma, Rociar, Parar"]'::jsonb,0,'Pull the pin, aim at the base, squeeze, sweep side to side. Only if safe and the fire is small.','Jala el seguro, apunta a la base, aprieta y barre de lado a lado. Solo si es seguro y el fuego es pequeño.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers'),
('all','all','emergency','The fire alarm goes off. What should you do?','Suena la alarma de incendio. ¿Qué debes hacer?','["Wait to see if it stops", "Follow the hotel''s emergency plan—never use elevators", "Take the elevator down"]'::jsonb,'["Esperar a ver si se apaga", "Seguir el plan de emergencia del hotel; nunca usar elevadores", "Bajar en elevador"]'::jsonb,1,'Use stairs and follow your assigned role in the plan.','Usa las escaleras y sigue tu función en el plan.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers'),
('all','all','security','Someone in the hall says they''re locked out and asks you to open a room. You:','Alguien en el pasillo dice que se quedó afuera y te pide abrir una habitación. Tú:','["Open it to be helpful", "Politely send them to the front desk to verify ID", "Lend your master key"]'::jsonb,'["La abres para ayudar", "Lo envías amablemente a recepción para verificar su identificación", "Le prestas tu llave maestra"]'::jsonb,1,'Never open a door without verification. The desk confirms identity first.','Nunca abras sin verificación. Recepción confirma la identidad primero.','general hospitality best practice'),
('all','all','privacy','A caller asks, ''What room is John Smith in?'' The right response:','Alguien llama y pregunta: ''¿En qué habitación está John Smith?'' La respuesta correcta:','["Say he checked out", "Give the number", "Never give room numbers; offer to connect the call"]'::jsonb,'["Decir que ya salió", "Dar el número", "Nunca dar números de habitación; ofrecer transferir la llamada"]'::jsonb,2,'Guest room numbers are private. Connect the call without confirming the room.','El número de habitación es privado. Transfiere sin confirmar la habitación.','general hospitality best practice'),
('all','all','security','Your master key should be:','Tu llave maestra debe:','["Kept on you at all times and never loaned", "Left on the cart", "Shared with coworkers"]'::jsonb,'["Estar contigo en todo momento y nunca prestarse", "Dejarse en el carrito", "Compartirse con compañeros"]'::jsonb,0,'Master keys open every door. Lost keys must be reported immediately.','Las llaves maestras abren todas las puertas. Reporta una pérdida de inmediato.','general hospitality best practice'),
('all','all','security','Possible human trafficking sign at a hotel?','¿Posible señal de trata de personas en un hotel?','["A guest asking for towels", "A family with luggage", "Someone who seems controlled, can''t speak for themselves, many visitors to one room"]'::jsonb,'["Un huésped pidiendo toallas", "Una familia con maletas", "Alguien que parece controlado, no puede hablar por sí mismo, muchas visitas a una habitación"]'::jsonb,2,'Don''t confront. Report what you saw to a manager.','No confrontes. Reporta lo que viste a un gerente.','https://www.dhs.gov/blue-campaign'),
('all','all','guest_service','A guest asks you for something outside your job. Best response?','Un huésped te pide algo fuera de tu trabajo. ¿Mejor respuesta?','["Ignore them", "''I''ll get that for you''—then hand it off and follow up", "''That''s not my department''"]'::jsonb,'["Ignorarlo", "''Con gusto se lo consigo'' y luego pásalo y da seguimiento", "''Ese no es mi departamento''"]'::jsonb,1,'Own the request even if someone else completes it.','Hazte cargo aunque otra persona lo complete.','general hospitality best practice'),
('all','all','guest_service','The 10-5 rule means:','La regla 10-5 significa:','["Smile/eye contact at 10 ft, greet at 5 ft", "Clean 10 rooms in 5 hours", "Take 10 breaks"]'::jsonb,'["Sonreír a 10 pies y saludar a 5 pies", "Limpiar 10 habitaciones en 5 horas", "Tomar 10 descansos"]'::jsonb,0,'A common hospitality habit to make every guest feel welcome.','Un hábito común en hotelería para que todos se sientan bienvenidos.','general hospitality best practice'),
('all','all','safety','How long should you scrub hands with soap?','¿Cuánto tiempo debes frotarte las manos con jabón?','["5 seconds", "2 minutes", "At least 20 seconds"]'::jsonb,'["5 segundos", "2 minutos", "Al menos 20 segundos"]'::jsonb,2,'CDC: scrub at least 20 seconds.','CDC: frota al menos 20 segundos.','https://www.cdc.gov/clean-hands/about/index.html'),
('all','all','safety','You cut your hand at work. What should you do?','Te cortas la mano en el trabajo. ¿Qué haces?','["Get first aid and report it to your manager the same day", "Report it next week", "Keep working and say nothing"]'::jsonb,'["Recibir primeros auxilios y reportarlo a tu gerente el mismo día", "Reportarlo la próxima semana", "Seguir trabajando sin decir nada"]'::jsonb,0,'Report every injury right away, even small ones.','Reporta toda lesión de inmediato, aunque sea pequeña.','general hospitality best practice'),
('all','all','safety','Gloves for cleaning blood or body fluids should be:','Los guantes para limpiar sangre o fluidos deben ser:','["Optional", "Washed and reused", "Disposable and thrown away after one use"]'::jsonb,'["Opcionales", "Lavados y reusados", "Desechables y tirarse después de un uso"]'::jsonb,2,'Use PPE, bag waste, then wash your hands.','Usa equipo de protección, embolsa los desechos y lávate las manos.','https://www.osha.gov/bloodborne-pathogens'),
('all','all','privacy','A guest leaves a phone in the lobby. You:','Un huésped deja un teléfono en el lobby. Tú:','["Look through it to find the owner", "Log it in lost & found and give it to the desk", "Keep it until someone asks"]'::jsonb,'["Revisarlo para encontrar al dueño", "Registrarlo en objetos perdidos y entregarlo a recepción", "Guardarlo hasta que alguien pregunte"]'::jsonb,1,'Log it, secure it, and release only after verifying the owner.','Regístralo, guárdalo y entrégalo solo tras verificar al dueño.','general hospitality best practice'),
('all','all','security','A stranger is waiting by a staff-only door. You:','Un desconocido espera junto a una puerta solo para personal. Tú:','["Ask politely if you can help and don''t let them follow you in", "Ignore it", "Hold the door open"]'::jsonb,'["Preguntar amablemente si puedes ayudar y no dejar que entre contigo", "Ignorarlo", "Sostener la puerta"]'::jsonb,0,'Prevent tailgating into back-of-house areas.','Evita que alguien entre detrás de ti a áreas de personal.','general hospitality best practice'),
('all','all','guest_service','A guest complains to you. First step?','Un huésped se queja contigo. ¿Primer paso?','["Explain why it''s not your fault", "Interrupt with a solution", "Listen fully and apologize"]'::jsonb,'["Explicar que no es tu culpa", "Interrumpir con una solución", "Escuchar completo y disculparte"]'::jsonb,2,'Listen, apologize, solve, follow up.','Escucha, discúlpate, resuelve y da seguimiento.','general hospitality best practice'),
('all','all','safety','A cleaning bottle has no label. You should:','Una botella de limpieza no tiene etiqueta. Debes:','["Not use it and report it", "Guess by smell", "Use it if it looks like water"]'::jsonb,'["No usarla y reportarla", "Adivinar por el olor", "Usarla si parece agua"]'::jsonb,0,'Every chemical container must be labeled.','Todo envase de químico debe estar etiquetado.','https://www.osha.gov/hazcom'),
('all','all','emergency','During severe weather (tornado warning) guests should go to:','Durante un aviso de tornado, los huéspedes deben ir a:','["The hotel''s designated shelter area, away from windows", "The parking lot", "Their cars"]'::jsonb,'["El área de refugio designada del hotel, lejos de ventanas", "El estacionamiento", "Sus autos"]'::jsonb,0,'Know your hotel''s shelter area before you need it.','Conoce el área de refugio del hotel antes de necesitarla.','https://www.ready.gov/tornadoes'),
('all','front_desk','security','A guest at the desk asks for a new key. Before making it you:','Un huésped pide una llave nueva. Antes de hacerla:','["Verify photo ID matches the registered guest", "Make it if they seem nice", "Ask their room number only"]'::jsonb,'["Verificar que su identificación con foto coincida con el huésped registrado", "Hacerla si parece amable", "Preguntar solo el número de habitación"]'::jsonb,0,'Room number alone is not proof. Verify ID every time.','El número de habitación no es prueba. Verifica la identificación siempre.','general hospitality best practice'),
('all','front_desk','privacy','When handing a new key, you should:','Al entregar una llave nueva debes:','["Announce the number", "Write or point to the room number, not say it out loud", "Write it on the key"]'::jsonb,'["Decir el número en voz alta", "Escribir o señalar el número, no decirlo en voz alta", "Escribirlo en la llave"]'::jsonb,1,'Saying room numbers aloud lets others hear.','Decir el número en voz alta permite que otros escuchen.','general hospitality best practice'),
('all','front_desk','privacy','A caller says they''re the guest''s spouse and wants the guest''s account details. You:','Alguien que dice ser el cónyuge del huésped pide información de la cuenta. Tú:','["Give the room number", "Share it", "Don''t share details unless they''re on the reservation and verified"]'::jsonb,'["Dar el número de habitación", "Compartirlo", "No compartir datos a menos que esté en la reserva y verificado"]'::jsonb,2,'Only registered, verified guests get account info.','Solo huéspedes registrados y verificados reciben esa información.','general hospitality best practice'),
('all','front_desk','privacy','Can you write down a guest''s full card number to charge later?','¿Puedes anotar el número completo de tarjeta de un huésped para cobrar después?','["Yes, on a sticky note", "Yes, in shift notes", "No—never write or store full card numbers"]'::jsonb,'["Sí, en una nota adhesiva", "Sí, en las notas de turno", "No, nunca anotes ni guardes números completos de tarjeta"]'::jsonb,2,'Card data must stay in the PMS/terminal (PCI security).','Los datos de tarjeta deben quedarse en el sistema o terminal (seguridad PCI).','https://www.pcisecuritystandards.org/'),
('all','front_desk','guest_service','A guest arrives and their room isn''t ready. Best move?','Llega un huésped y su habitación no está lista. ¿Mejor acción?','["Give a dirty room", "Say ''come back later''", "Apologize, offer to hold bags, give a time, and follow up"]'::jsonb,'["Dar una habitación sucia", "Decir ''regrese más tarde''", "Disculparte, ofrecer guardar el equipaje, dar una hora y dar seguimiento"]'::jsonb,2,'Set expectations and follow up.','Fija expectativas y da seguimiento.','general hospitality best practice'),
('all','front_desk','guest_service','Using the guest''s name at check-in:','Usar el nombre del huésped al registrarse:','["Builds a personal connection", "Is unprofessional", "Should be avoided"]'::jsonb,'["Crea una conexión personal", "Es poco profesional", "Debe evitarse"]'::jsonb,0,'Use their name naturally, at least once or twice.','Usa su nombre con naturalidad una o dos veces.','general hospitality best practice'),
('all','front_desk','night_audit','What''s the main purpose of the night audit?','¿Cuál es el propósito principal de la auditoría nocturna?','["Make the schedule", "Clean the lobby", "Balance the day''s charges and payments and roll the date"]'::jsonb,'["Hacer el horario", "Limpiar el lobby", "Cuadrar cargos y pagos del día y cambiar la fecha"]'::jsonb,2,'Night audit reconciles revenue and closes the business day.','La auditoría concilia ingresos y cierra el día.','general hospitality best practice'),
('all','front_desk','night_audit','Before running the audit you should check:','Antes de correr la auditoría debes revisar:','["Nothing", "Only the weather", "No-shows, rates, and that every in-house room is posted"]'::jsonb,'["Nada", "Solo el clima", "No-shows, tarifas y que todas las habitaciones ocupadas tengan cargo"]'::jsonb,2,'Errors are easier to fix before the date rolls.','Los errores son más fáciles de corregir antes de cerrar.','general hospitality best practice'),
('all','front_desk','security','A visitor asks to be let into a guest''s room to wait. You:','Un visitante pide entrar a la habitación de un huésped a esperar. Tú:','["Give them a key", "Let them in", "Call the guest; only they can authorize"]'::jsonb,'["Darle una llave", "Dejarlo entrar", "Llamar al huésped; solo él puede autorizar"]'::jsonb,2,'Never grant access to non-registered people without the guest''s OK.','Nunca des acceso a no registrados sin permiso del huésped.','general hospitality best practice'),
('all','front_desk','guest_service','Phone etiquette: answer within how many rings?','Teléfono: ¿contestar dentro de cuántos timbres?','["10", "3", "6"]'::jsonb,'["10", "3", "6"]'::jsonb,1,'Common standard: within three rings with a warm greeting.','Estándar común: dentro de 3 timbres con un saludo cordial.','general hospitality best practice'),
('all','front_desk','security','The ID presented doesn''t match the reservation name. You:','La identificación no coincide con el nombre de la reserva. Tú:','["Don''t check in until it''s resolved per policy/manager", "Change the name yourself", "Check in anyway"]'::jsonb,'["No registrar hasta resolverlo según la política o el gerente", "Cambiar el nombre tú mismo", "Registrar de todos modos"]'::jsonb,0,'Follow the hotel''s ID policy; ask a manager.','Sigue la política de identificación; consulta al gerente.','general hospitality best practice'),
('all','front_desk','guest_service','A guest asks for a restaurant recommendation. Best answer?','Un huésped pide recomendación de restaurante. ¿Mejor respuesta?','["Say ''use Google''", "Ask what they like, suggest 2–3 nearby, give directions", "Name one place you''ve never been"]'::jsonb,'["Decir ''use Google''", "Preguntar qué le gusta, sugerir 2 o 3 cercanos y dar direcciones", "Nombrar uno donde nunca has ido"]'::jsonb,1,'Personal, local knowledge makes a great stay.','El conocimiento local personal hace una gran estancia.','general hospitality best practice'),
('all','front_desk','security','Cash drawer best practice at shift change?','¿Buena práctica con la caja al cambiar de turno?','["Leave it for the next shift", "Count with the next person and sign off", "Count it alone later"]'::jsonb,'["Dejarla para el siguiente turno", "Contarla con la siguiente persona y firmar", "Contarla solo después"]'::jsonb,1,'Dual counts protect you and the hotel.','El conteo doble te protege a ti y al hotel.','general hospitality best practice'),
('all','front_desk','safety','A guest says they feel unsafe because of someone in the hall. You:','Un huésped dice que se siente inseguro por alguien en el pasillo. Tú:','["Take it seriously, notify the manager, call 911 if there''s a threat", "Tell them it''s fine", "Go confront alone"]'::jsonb,'["Tomarlo en serio, avisar al gerente, llamar al 911 si hay amenaza", "Decir que todo está bien", "Confrontar solo"]'::jsonb,0,'Safety first; don''t confront alone.','La seguridad primero; no confrontes solo.','general hospitality best practice'),
('all','front_desk','guest_service','Best time to mention the loyalty program?','¿Mejor momento para mencionar el programa de lealtad?','["Only if asked", "Never", "During check-in, after the greeting"]'::jsonb,'["Solo si preguntan", "Nunca", "Durante el registro, después del saludo"]'::jsonb,2,'Ask every non-member at check-in.','Pregunta a cada no socio durante el registro.','general hospitality best practice'),
('all','front_desk','privacy','Can you post a guest''s photo or name on your personal social media?','¿Puedes publicar la foto o el nombre de un huésped en tus redes?','["Yes, if they''re rude", "Yes, if famous", "No"]'::jsonb,'["Sí, si es grosero", "Sí, si es famoso", "No"]'::jsonb,2,'Guest privacy extends to social media.','La privacidad del huésped también aplica a redes sociales.','general hospitality best practice'),
('all','housekeeping','housekeeping','When cleaning a room, which order is best?','Al limpiar una habitación, ¿qué orden es mejor?','["Bathroom last only", "Top to bottom, clean to dirty", "Floor first"]'::jsonb,'["Solo el baño al final", "De arriba hacia abajo, de limpio a sucio", "El piso primero"]'::jsonb,1,'Dust falls down; finish with floors.','El polvo cae; termina con el piso.','general hospitality best practice'),
('all','housekeeping','housekeeping','Why use separate cloths for toilets and glasses?','¿Por qué usar paños distintos para el inodoro y los vasos?','["To prevent cross-contamination", "To save time", "It doesn''t matter"]'::jsonb,'["Para evitar contaminación cruzada", "Para ahorrar tiempo", "No importa"]'::jsonb,0,'Color-code cloths and never mix them.','Usa paños por colores y nunca los mezcles.','general hospitality best practice'),
('all','housekeeping','housekeeping','Disinfectant contact (dwell) time means:','El tiempo de contacto del desinfectante significa:','["Leave it wet on the surface for the time on the label", "Wipe immediately", "Spray twice"]'::jsonb,'["Dejarlo húmedo el tiempo que indica la etiqueta", "Limpiar de inmediato", "Rociar dos veces"]'::jsonb,0,'Wiping too soon means it doesn''t disinfect.','Si limpias muy pronto, no desinfecta.','https://www.epa.gov/pesticide-registration/selected-epa-registered-disinfectants'),
('all','housekeeping','housekeeping','A ''Do Not Disturb'' sign is on the door. You:','Hay un letrero de ''No molestar''. Tú:','["Don''t enter; follow the hotel''s DND welfare-check policy", "Knock loudly and enter", "Slide a note and enter"]'::jsonb,'["No entrar; seguir la política de revisión de bienestar del hotel", "Tocar fuerte y entrar", "Deslizar una nota y entrar"]'::jsonb,0,'Respect DND, but report long DNDs to your supervisor.','Respeta el letrero, pero reporta los que duran mucho a tu supervisor.','general hospitality best practice'),
('all','housekeeping','housekeeping','How should you enter a guest room?','¿Cómo debes entrar a una habitación?','["Just open it", "Enter if lights are off", "Knock, announce ''Housekeeping,'' wait, repeat, then enter"]'::jsonb,'["Abrir directamente", "Entrar si las luces están apagadas", "Tocar, decir ''Housekeeping'', esperar, repetir y entrar"]'::jsonb,2,'Always announce yourself to protect guest privacy.','Anúnciate siempre para proteger la privacidad.','general hospitality best practice'),
('all','housekeeping','housekeeping','While cleaning, the room door should be:','Mientras limpias, la puerta debe estar:','["Wide open with cart away", "Locked with you inside always", "Propped/with cart blocking per hotel policy"]'::jsonb,'["Abierta y el carrito lejos", "Cerrada contigo adentro siempre", "Abierta o con el carrito bloqueando según la política"]'::jsonb,2,'Follow your hotel''s door policy; it keeps you safe and signals you''re working.','Sigue la política del hotel; te protege y muestra que estás trabajando.','general hospitality best practice'),
('all','housekeeping','safety','You find blood on sheets. What do you do?','Encuentras sangre en las sábanas. ¿Qué haces?','["Wear gloves, bag it per the bloodborne pathogen procedure, tell your supervisor", "Wash it with bare hands", "Shake it out"]'::jsonb,'["Usar guantes, embolsarla según el procedimiento de patógenos y avisar al supervisor", "Lavarla con las manos", "Sacudirla"]'::jsonb,0,'Treat all blood as potentially infectious.','Trata toda la sangre como potencialmente infecciosa.','https://www.osha.gov/bloodborne-pathogens'),
('all','housekeeping','housekeeping','Signs of bed bugs include:','Señales de chinches incluyen:','["White powder", "Wet towels", "Small rust/dark spots on mattress seams"]'::jsonb,'["Polvo blanco", "Toallas mojadas", "Pequeñas manchas oscuras u oxidadas en las costuras del colchón"]'::jsonb,2,'Don''t remove anything; close the room and report right away.','No saques nada; cierra la habitación y repórtalo de inmediato.','https://www.epa.gov/bedbugs'),
('all','housekeeping','housekeeping','A guest left cash on the nightstand in a stayover. You:','Un huésped dejó dinero en la mesa de noche (estancia continua). Tú:','["Take it as a tip", "Leave it exactly where it is", "Put it in lost & found"]'::jsonb,'["Tomarlo como propina", "Dejarlo exactamente donde está", "Llevarlo a objetos perdidos"]'::jsonb,1,'Never move guest valuables in an occupied room. Only clearly marked tips are yours.','Nunca muevas objetos de valor en una habitación ocupada. Solo es tuya la propina claramente marcada.','general hospitality best practice'),
('all','housekeeping','housekeeping','Items found in a checkout room go to:','Los objetos en una habitación de salida van a:','["Lost & found, logged with room, date, and finder", "The trash", "Your locker"]'::jsonb,'["Objetos perdidos, registrados con habitación, fecha y quién los encontró", "La basura", "Tu casillero"]'::jsonb,0,'Log everything so the guest can get it back.','Registra todo para que el huésped lo recupere.','general hospitality best practice'),
('all','housekeeping','safety','Best way to move a heavy mattress?','¿Mejor forma de mover un colchón pesado?','["Get a partner and use legs, not back", "Pull it alone quickly", "Lift by twisting"]'::jsonb,'["Con un compañero y usando las piernas, no la espalda", "Jalarlo solo rápido", "Levantarlo girando"]'::jsonb,0,'Team lifts prevent back injuries.','Levantar en equipo evita lesiones de espalda.','https://www.cdc.gov/niosh/ergonomics/index.html'),
('all','housekeeping','housekeeping','Before leaving a finished room, do a final:','Antes de salir de una habitación terminada, haz una revisión final:','["Walk-through from the guest''s view", "Phone call", "Nap"]'::jsonb,'["Recorrido desde la vista del huésped", "Llamada", "Siesta"]'::jsonb,0,'Look at it like the guest will: hair, smudges, amenities.','Mírala como el huésped: cabellos, manchas, amenidades.','general hospitality best practice'),
('all','housekeeping','housekeeping','You find a broken lamp in a room. You:','Encuentras una lámpara rota. Tú:','["Leave it", "Hide it", "Report it as a work order right away"]'::jsonb,'["Dejarla", "Esconderla", "Reportarla como orden de trabajo de inmediato"]'::jsonb,2,'Report it so it''s fixed before the guest arrives.','Repórtala para que se arregle antes de que llegue el huésped.','general hospitality best practice'),
('all','housekeeping','safety','Your vacuum cord is frayed. You:','El cable de tu aspiradora está pelado. Tú:','["Ignore it", "Tape it and keep going", "Stop using it, tag it, report it"]'::jsonb,'["Ignorarlo", "Ponerle cinta y seguir", "Dejar de usarla, etiquetarla y reportarla"]'::jsonb,2,'Damaged cords can shock or start a fire.','Un cable dañado puede electrocutar o causar fuego.','https://www.osha.gov/electrical'),
('all','housekeeping','laundry','Why separate heavily soiled linens?','¿Por qué separar ropa de cama muy sucia?','["They need different treatment and protect clean linen", "To make piles smaller", "No reason"]'::jsonb,'["Necesitan otro tratamiento y protegen la ropa limpia", "Para hacer pilas más chicas", "Sin razón"]'::jsonb,0,'Sort by soil and type; stained items get treated before washing.','Separa por suciedad y tipo; trata las manchas antes de lavar.','general hospitality best practice'),
('all','housekeeping','laundry','Lint in the dryer filter should be cleaned:','La pelusa del filtro de la secadora se limpia:','["Every load or per the manufacturer", "Once a month", "Never"]'::jsonb,'["Cada carga o según el fabricante", "Una vez al mes", "Nunca"]'::jsonb,0,'Lint buildup is a fire hazard.','La pelusa acumulada es riesgo de incendio.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/'),
('all','housekeeping','housekeeping','When you finish a room and inspection finds an issue, the best attitude is:','Si al terminar una habitación la inspección encuentra un problema, la mejor actitud es:','["Argue", "Hide it next time", "Fix it and learn the standard"]'::jsonb,'["Discutir", "Esconderlo la próxima vez", "Arreglarlo y aprender el estándar"]'::jsonb,2,'Inspections help everyone hit the standard (and earn points!).','Las inspecciones ayudan a cumplir el estándar (¡y ganar puntos!).','general hospitality best practice'),
('all','maintenance','maintenance','Lockout/tagout is used to:','El bloqueo/etiquetado (LOTO) se usa para:','["Lock guest rooms", "Make sure equipment can''t start or release energy while you work on it", "Track keys"]'::jsonb,'["Cerrar habitaciones", "Asegurar que el equipo no arranque ni libere energía mientras trabajas", "Controlar llaves"]'::jsonb,1,'Isolate, lock, tag, and verify zero energy.','Aísla, bloquea, etiqueta y verifica energía cero.','https://www.osha.gov/control-hazardous-energy'),
('all','maintenance','maintenance','After applying your lock, what''s the next step?','Después de poner tu candado, ¿qué sigue?','["Remove the tag", "Start working right away", "Verify the equipment is de-energized (try to start it)"]'::jsonb,'["Quitar la etiqueta", "Empezar a trabajar de inmediato", "Verificar que el equipo no tenga energía (intentar arrancarlo)"]'::jsonb,2,'Always verify before you touch.','Siempre verifica antes de tocar.','https://www.osha.gov/control-hazardous-energy'),
('all','maintenance','maintenance','Who can remove your lockout lock?','¿Quién puede quitar tu candado LOTO?','["Any coworker", "Only you (except under the formal removal procedure)", "The guest"]'::jsonb,'["Cualquier compañero", "Solo tú (salvo el procedimiento formal)", "El huésped"]'::jsonb,1,'Your lock, your key.','Tu candado, tu llave.','https://www.osha.gov/control-hazardous-energy'),
('all','maintenance','safety','On a ladder you should keep how many points of contact?','En una escalera, ¿cuántos puntos de apoyo debes mantener?','["3", "1", "2"]'::jsonb,'["3", "1", "2"]'::jsonb,0,'Two hands and a foot, or two feet and a hand.','Dos manos y un pie, o dos pies y una mano.','https://www.osha.gov/ladders'),
('all','maintenance','safety','Never stand on which part of a step ladder?','¿En qué parte de una escalera de tijera nunca debes pararte?','["The bottom step", "The top cap or top step", "The middle"]'::jsonb,'["El primer peldaño", "La parte superior o último peldaño", "El medio"]'::jsonb,1,'Use a taller ladder instead.','Usa una escalera más alta.','https://www.osha.gov/ladders'),
('all','maintenance','maintenance','A GFCI outlet protects against:','Un tomacorriente GFCI protege contra:','["Electric shock near water", "Wi-Fi drops", "Power bills"]'::jsonb,'["Descargas eléctricas cerca del agua", "Fallas de Wi-Fi", "Facturas de luz"]'::jsonb,0,'Test GFCIs during PMs; required in wet areas.','Prueba los GFCI en el mantenimiento; se requieren en áreas húmedas.','https://www.osha.gov/electrical'),
('all','maintenance','maintenance','Why do PMs on PTACs/HVAC units?','¿Por qué hacer mantenimiento preventivo a los PTAC/HVAC?','["Fewer breakdowns, better air, fewer complaints", "Only for show", "It voids warranty"]'::jsonb,'["Menos fallas, mejor aire, menos quejas", "Solo por apariencia", "Anula la garantía"]'::jsonb,0,'Clean filters and coils keep rooms comfortable and sellable.','Filtros y serpentines limpios mantienen las habitaciones cómodas y vendibles.','general hospitality best practice'),
('all','maintenance','maintenance','A room is out of order. When it''s fixed, you should:','Una habitación está fuera de servicio. Cuando se repare, debes:','["Close the work order and tell the desk/HK right away", "Tell no one", "Wait until tomorrow"]'::jsonb,'["Cerrar la orden y avisar a recepción y limpieza de inmediato", "No avisar", "Esperar a mañana"]'::jsonb,0,'Every OOO night is lost revenue.','Cada noche fuera de servicio es ingreso perdido.','general hospitality best practice'),
('all','maintenance','maintenance','Before working on a guest room, you:','Antes de trabajar en una habitación con huésped, tú:','["Walk in", "Use the guest''s bathroom", "Knock, announce, and get permission if occupied"]'::jsonb,'["Entrar", "Usar el baño del huésped", "Tocar, anunciarte y pedir permiso si está ocupada"]'::jsonb,2,'Same entry rules as housekeeping.','Las mismas reglas de entrada que limpieza.','general hospitality best practice'),
('all','maintenance','safety','Pool chemicals should be stored:','Los químicos de piscina se guardan:','["Next to the boiler", "Separately, dry, labeled, and never mixed", "All together on one shelf"]'::jsonb,'["Junto a la caldera", "Por separado, secos, etiquetados y nunca mezclados", "Todos juntos"]'::jsonb,1,'Some pool chemicals react violently together.','Algunos químicos de piscina reaccionan violentamente juntos.','https://www.cdc.gov/healthy-swimming/prevention/preventing-pool-chemical-injuries.html'),
('all','maintenance','safety','Safety glasses are needed when:','Se necesitan lentes de seguridad cuando:','["Answering phones", "Drilling, grinding, or handling chemicals", "Walking hallways"]'::jsonb,'["Contestas teléfonos", "Taladras, esmerilas o usas químicos", "Caminas por pasillos"]'::jsonb,1,'Protect your eyes from debris and splashes.','Protege tus ojos de partículas y salpicaduras.','https://www.osha.gov/eye-face-protection'),
('all','maintenance','maintenance','Fire extinguishers should be checked:','Los extintores se revisan:','["Only after a fire", "Every 5 years only", "Monthly visual check, plus annual service"]'::jsonb,'["Solo después de un incendio", "Solo cada 5 años", "Revisión visual mensual y servicio anual"]'::jsonb,2,'Check gauge, pin, seal, and access monthly.','Revisa manómetro, seguro, sello y acceso cada mes.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers'),
('all','maintenance','maintenance','Water heater temperature is commonly set around:','La temperatura del calentador de agua suele estar cerca de:','["120°F at the tap to prevent scalding", "90°F", "180°F"]'::jsonb,'["120°F en la llave para evitar quemaduras", "90°F", "180°F"]'::jsonb,0,'Hotter water at the tap can scald guests. Follow your property''s setpoint.','El agua más caliente puede quemar. Sigue la configuración del hotel.','https://www.cpsc.gov/safety-education/safety-guides/kitchen/tap-water-scalds'),
('all','maintenance','maintenance','A guest reports a smell of gas. First step?','Un huésped reporta olor a gas. ¿Primer paso?','["Wait", "Light a match to find it", "Don''t use switches or flames; evacuate the area and call the gas company/911"]'::jsonb,'["Esperar", "Encender un cerillo para encontrarlo", "No uses interruptores ni flamas; evacua y llama a la compañía de gas o al 911"]'::jsonb,2,'Sparks can ignite gas.','Una chispa puede encender el gas.','https://www.centerpointenergy.com/en-us/safety'),
('all','maintenance','maintenance','Emergency exit lights should be:','Las luces de salida de emergencia deben:','["Only on at night", "Off to save power", "Lit at all times and tested regularly"]'::jsonb,'["Solo de noche", "Apagadas para ahorrar", "Estar encendidas siempre y probarse con regularidad"]'::jsonb,2,'Guests need them in smoke or power loss.','Los huéspedes las necesitan con humo o sin luz.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/exit-routes'),
('all','maintenance','maintenance','Closing a work order with a photo helps by:','Cerrar una orden con foto ayuda porque:','["Proving the fix and speeding follow-up", "Nothing", "Slowing things down"]'::jsonb,'["Prueba la reparación y agiliza el seguimiento", "Nada", "Hace todo lento"]'::jsonb,0,'Photos also earn points in the app.','Las fotos también ganan puntos en la app.','general hospitality best practice'),
('all','breakfast','food_safety','Hot foods on the buffet must be held at:','Los alimentos calientes del buffet deben mantenerse a:','["120°F", "135°F or above", "100°F"]'::jsonb,'["120°F", "135°F o más", "100°F"]'::jsonb,1,'FDA Food Code: hot holding at 135°F or above.','Código Alimentario de la FDA: mantener caliente a 135°F o más.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','Cold foods (milk, yogurt) must be held at:','Los alimentos fríos (leche, yogur) deben mantenerse a:','["50°F", "45°F", "41°F or below"]'::jsonb,'["50°F", "45°F", "41°F o menos"]'::jsonb,2,'Cold holding: 41°F or below.','Mantener frío: 41°F o menos.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','The temperature ''danger zone'' is:','La ''zona de peligro'' de temperatura es:','["150°F–200°F", "41°F–135°F", "0°F–32°F"]'::jsonb,'["150°F–200°F", "41°F–135°F", "0°F–32°F"]'::jsonb,1,'Bacteria grow fastest between 41°F and 135°F.','Las bacterias crecen más rápido entre 41°F y 135°F.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','Reheating food for hot holding: it must reach:','Recalentar para mantener caliente: debe llegar a:','["120°F", "140°F in 6 hours", "165°F within 2 hours"]'::jsonb,'["120°F", "140°F en 6 horas", "165°F en 2 horas"]'::jsonb,2,'Reheat to 165°F within 2 hours.','Recalienta a 165°F en menos de 2 horas.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','How should you check a food''s temperature?','¿Cómo debes revisar la temperatura?','["Touch it", "Look at the steam", "Calibrated probe thermometer in the thickest part"]'::jsonb,'["Tocarlo", "Ver el vapor", "Termómetro de sonda calibrado en la parte más gruesa"]'::jsonb,2,'Log temps on the checklist.','Registra las temperaturas en la lista.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','When do you need to change gloves?','¿Cuándo debes cambiar los guantes?','["Once a shift", "Never", "When torn, switching tasks, or after touching raw food or your face"]'::jsonb,'["Una vez por turno", "Nunca", "Si se rompen, al cambiar de tarea o tras tocar comida cruda o tu cara"]'::jsonb,2,'Wash hands before putting on new gloves.','Lávate las manos antes de ponerte guantes nuevos.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','A guest asks if an item has nuts. You aren''t sure. You:','Un huésped pregunta si algo tiene nueces. No estás seguro. Tú:','["Say yes to be safe and walk away", "Say you''ll check the label/manager—never guess", "Say ''probably not''"]'::jsonb,'["Decir que sí y alejarte", "Decir que revisarás la etiqueta o al gerente; nunca adivinar", "Decir ''probablemente no''"]'::jsonb,1,'Allergies can be life-threatening. Check labels.','Las alergias pueden ser mortales. Revisa etiquetas.','https://www.fda.gov/food/food-labeling-nutrition/food-allergies'),
('all','breakfast','food_safety','Thawing frozen food safely means:','Descongelar de forma segura significa:','["In the fridge, under cold running water, or as part of cooking", "On the counter overnight", "In hot water"]'::jsonb,'["En el refrigerador, bajo agua fría corriendo o al cocinar", "En la barra toda la noche", "En agua caliente"]'::jsonb,0,'Never thaw at room temperature.','Nunca descongeles a temperatura ambiente.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','FIFO means:','FIFO significa:','["Fresh Items First Only", "First In, First Out—use older stock first", "Fill It Full Often"]'::jsonb,'["Solo productos frescos", "Primero en entrar, primero en salir: usa lo más viejo primero", "Llenar seguido"]'::jsonb,1,'Rotate stock and check dates.','Rota el inventario y revisa fechas.','general hospitality best practice'),
('all','breakfast','food_safety','Cooked eggs held for the buffet must be cooked to at least:','Los huevos cocidos para el buffet deben cocinarse al menos a:','["135°F", "120°F", "155°F"]'::jsonb,'["135°F", "120°F", "155°F"]'::jsonb,2,'Food Code: eggs for hot holding cooked to 155°F (for 17 sec).','Código: huevos para mantener calientes a 155°F (17 segundos).','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','You''re sick with vomiting or diarrhea. You should:','Tienes vómito o diarrea. Debes:','["Tell your manager and not work with food", "Work if it''s busy", "Wear gloves and work"]'::jsonb,'["Avisar al gerente y no trabajar con comida", "Trabajar si hay mucho trabajo", "Usar guantes y trabajar"]'::jsonb,0,'Sick workers must be excluded from food handling.','Un empleado enfermo no debe manipular alimentos.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','Sanitizer buckets should be:','Las cubetas de desinfectante deben:','["Tested with strips and kept at label strength", "Mixed with soap", "Any strength"]'::jsonb,'["Probarse con tiras y estar a la concentración de la etiqueta", "Mezclarse con jabón", "De cualquier concentración"]'::jsonb,0,'Too weak won''t sanitize; too strong is unsafe.','Muy débil no desinfecta; muy fuerte no es seguro.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','breakfast','Breakfast is ending. A guest walks in 2 minutes before close. You:','Termina el desayuno y llega un huésped 2 minutos antes. Tú:','["Say it''s closed", "Welcome them and offer what''s available or a grab-and-go", "Start breaking down in front of them"]'::jsonb,'["Decir que está cerrado", "Darle la bienvenida y ofrecer lo disponible o algo para llevar", "Empezar a recoger frente a él"]'::jsonb,1,'Friendly flexibility earns great reviews.','La flexibilidad amable gana buenas reseñas.','general hospitality best practice'),
('all','breakfast','breakfast','Cleaning tables during service, you should:','Al limpiar mesas durante el servicio debes:','["Wipe with sanitizer cloth, clear plates promptly", "Use the floor rag", "Leave until the end"]'::jsonb,'["Limpiar con paño desinfectante y retirar platos rápido", "Usar el trapo del piso", "Dejarlo para el final"]'::jsonb,0,'A clean room is part of a great breakfast.','Un área limpia es parte de un gran desayuno.','general hospitality best practice'),
('all','breakfast','food_safety','Food left out of temperature control too long should be:','La comida fuera de control de temperatura por mucho tiempo debe:','["Thrown away per your time-control rules", "Served faster", "Put back in the fridge"]'::jsonb,'["Desecharse según las reglas de control de tiempo", "Servirse más rápido", "Volver al refrigerador"]'::jsonb,0,'When in doubt, throw it out.','Si hay duda, tírala.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','breakfast','food_safety','Cooling cooked food: 135°F to 70°F within:','Enfriar comida cocida: de 135°F a 70°F en:','["2 hours", "12 hours", "6 hours"]'::jsonb,'["2 horas", "12 horas", "6 horas"]'::jsonb,0,'Then 70°F to 41°F within 4 more hours.','Luego de 70°F a 41°F en 4 horas más.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','driver','driver','Before your first trip each day, you should:','Antes del primer viaje del día debes:','["Just drive", "Do a pre-trip check: tires, lights, brakes, mirrors, wipers", "Check only fuel"]'::jsonb,'["Solo manejar", "Hacer una revisión: llantas, luces, frenos, espejos, limpiaparabrisas", "Revisar solo gasolina"]'::jsonb,1,'Report any defect before driving.','Reporta cualquier falla antes de manejar.','https://www.nhtsa.gov/road-safety'),
('all','driver','driver','In Minnesota, using a handheld phone while driving is:','En Minnesota, usar el teléfono en la mano mientras manejas es:','["Fine at red lights", "Fine for texts", "Illegal—hands-free only"]'::jsonb,'["Permitido en semáforo rojo", "Permitido para mensajes", "Ilegal; solo manos libres"]'::jsonb,2,'Minnesota''s hands-free law bans holding your phone while driving.','La ley de manos libres de Minnesota prohíbe sostener el teléfono al manejar.','https://dps.mn.gov/divisions/ots/hands-free'),
('all','driver','driver','A safe following distance in good weather is at least:','Una distancia segura en buen clima es al menos:','["Half a second", "3 seconds", "1 second"]'::jsonb,'["Medio segundo", "3 segundos", "1 segundo"]'::jsonb,1,'Add more time in rain, snow, or with a heavy van.','Agrega más tiempo con lluvia, nieve o una van cargada.','https://www.nhtsa.gov/road-safety'),
('all','driver','driver','Before pulling away, passengers should be:','Antes de arrancar, los pasajeros deben:','["Standing with bags", "Seated with seatbelts on where equipped", "Anywhere"]'::jsonb,'["De pie con maletas", "Sentados y con cinturón si hay", "En cualquier lugar"]'::jsonb,1,'Remind guests politely to buckle up.','Recuerda amablemente que se pongan el cinturón.','https://www.nhtsa.gov/road-safety'),
('all','driver','driver','On icy Minnesota roads you should:','En caminos con hielo en Minnesota debes:','["Slow down, brake gently, and leave extra space", "Brake hard", "Drive normally"]'::jsonb,'["Ir más lento, frenar suave y dejar más espacio", "Frenar fuerte", "Manejar normal"]'::jsonb,0,'Increase following distance a lot on ice.','Aumenta mucho la distancia en hielo.','https://dps.mn.gov/divisions/ots/winter-driving'),
('all','driver','safety','Loading heavy luggage, you should:','Al cargar maletas pesadas debes:','["Throw it", "Bend knees, keep it close, get help with very heavy bags", "Swing it up with your back"]'::jsonb,'["Lanzarla", "Doblar rodillas, mantenerla cerca y pedir ayuda si pesa mucho", "Subirla con la espalda"]'::jsonb,1,'Protect your back.','Protege tu espalda.','https://www.cdc.gov/niosh/ergonomics/index.html'),
('all','driver','driver','Backing up the shuttle, best practice is:','Al dar reversa al shuttle, lo mejor es:','["Back up fast", "Rely only on the camera", "Check mirrors, use a spotter if possible, go slow"]'::jsonb,'["Dar reversa rápido", "Confiar solo en la cámara", "Revisar espejos, usar ayudante si se puede, ir lento"]'::jsonb,2,'Avoid backing when you can; if not, go slow.','Evita la reversa si puedes; si no, ve lento.','https://www.nhtsa.gov/road-safety'),
('all','driver','driver','A passenger seems very intoxicated and aggressive. You:','Un pasajero parece muy ebrio y agresivo. Tú:','["Argue", "Kick them out on the highway", "Stay calm, don''t argue, call the desk/manager; call 911 if unsafe"]'::jsonb,'["Discutir", "Bajarlo en la carretera", "Mantener la calma, no discutir, llamar a recepción o al gerente; 911 si es peligroso"]'::jsonb,2,'Your safety and passengers'' safety come first.','Tu seguridad y la de los pasajeros es primero.','general hospitality best practice'),
('all','driver','driver','After an accident, first steps are:','Después de un accidente, los primeros pasos son:','["Check for injuries, call 911 if needed, then call your manager", "Leave the scene", "Argue fault"]'::jsonb,'["Revisar lesionados, llamar al 911 si hace falta y luego al gerente", "Irte del lugar", "Discutir de quién fue la culpa"]'::jsonb,0,'Never admit fault—just share facts and report.','No admitas culpa; comparte hechos y reporta.','general hospitality best practice'),
('all','driver','driver','Greeting airport guests, you should:','Al recibir huéspedes en el aeropuerto debes:','["Honk", "Smile, confirm the hotel and name, help with bags", "Wait in the van"]'::jsonb,'["Tocar el claxon", "Sonreír, confirmar el hotel y nombre, ayudar con maletas", "Esperar en la van"]'::jsonb,1,'You''re the first impression of the hotel.','Eres la primera impresión del hotel.','general hospitality best practice'),
('all','driver','driver','Fatigue while driving: you should:','Si tienes cansancio al manejar:','["Open the window and speed up", "Drink coffee and push on", "Pull over safely and tell your manager"]'::jsonb,'["Abrir la ventana y acelerar", "Tomar café y seguir", "Detenerte de forma segura y avisar al gerente"]'::jsonb,2,'Drowsy driving is dangerous.','Manejar con sueño es peligroso.','https://www.nhtsa.gov/risky-driving/drowsy-driving'),
('all','driver','driver','Keeping the shuttle tracker on helps because:','Mantener el rastreador del shuttle encendido ayuda porque:','["It''s not useful", "Staff and guests can see where you are and the ETA", "It slows the van"]'::jsonb,'["No sirve", "El personal y huéspedes ven dónde estás y la hora de llegada", "Hace lenta la van"]'::jsonb,1,'Fewer ''where''s the shuttle?'' calls.','Menos llamadas de ''¿dónde está el shuttle?''.','general hospitality best practice'),
('all','driver','driver','At the airport curb, you should:','En la acera del aeropuerto debes:','["Park anywhere", "Leave the van running unattended", "Follow airport rules and the posted hotel shuttle zone"]'::jsonb,'["Estacionarte donde sea", "Dejar la van encendida sola", "Seguir las reglas del aeropuerto y la zona de shuttles"]'::jsonb,2,'MSP has designated hotel shuttle pickup areas.','MSP tiene zonas designadas para shuttles de hoteles.','https://www.mspairport.com/transportation/hotel-shuttles'),
('all','driver','driver','A guest left a bag in the shuttle. You:','Un huésped dejó una bolsa en el shuttle. Tú:','["Leave it in the van", "Bring it to the desk and log it in lost & found", "Keep it"]'::jsonb,'["Dejarla en la van", "Llevarla a recepción y registrarla en objetos perdidos", "Quedártela"]'::jsonb,1,'Check the van after each trip.','Revisa la van después de cada viaje.','general hospitality best practice'),
('all','driver','driver','Speed limit vs. weather: you should drive:','Límite de velocidad y clima: debes manejar:','["Faster to stay on schedule", "Always at the limit", "At a speed safe for conditions, even below the limit"]'::jsonb,'["Más rápido para cumplir horario", "Siempre al límite", "A una velocidad segura para las condiciones, aunque sea menor al límite"]'::jsonb,2,'Being a bit late beats an accident.','Llegar un poco tarde es mejor que un accidente.','https://www.nhtsa.gov/road-safety'),
('all','driver','driver','When your shift ends, you should:','Al terminar tu turno debes:','["Nothing", "Just leave the keys", "Note fuel, mileage, and any issues for the next driver"]'::jsonb,'["Nada", "Solo dejar las llaves", "Anotar gasolina, millaje y problemas para el siguiente conductor"]'::jsonb,2,'Good handoffs keep the van safe.','Una buena entrega mantiene segura la van.','general hospitality best practice'),
('all','bartender','bar','Minnesota''s legal drinking age is:','La edad legal para beber en Minnesota es:','["19", "21", "18"]'::jsonb,'["19", "21", "18"]'::jsonb,1,'You may not serve anyone under 21.','No puedes servir a menores de 21.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','Who should you ID?','¿A quién debes pedir identificación?','["Nobody", "Anyone who looks under your hotel''s ID age (e.g., 30–40)", "Only people who look 15"]'::jsonb,'["A nadie", "A quien parezca menor de la edad de tu política (p. ej., 30–40)", "Solo a quien parezca de 15"]'::jsonb,1,'When in doubt, card them.','Si hay duda, pide identificación.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','Acceptable ID for alcohol is:','Una identificación aceptable para alcohol es:','["A school ID", "Valid, unexpired government photo ID", "A hotel key"]'::jsonb,'["Una credencial escolar", "Identificación oficial con foto vigente", "Una llave del hotel"]'::jsonb,1,'Check photo, date of birth, and expiration.','Revisa foto, fecha de nacimiento y vencimiento.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','Signs a guest is becoming intoxicated include:','Señales de que un huésped se está intoxicando:','["Asking for the menu", "Slurred speech, loud, stumbling, spilling drinks", "Ordering water"]'::jsonb,'["Pedir el menú", "Habla arrastrada, ruido, tropiezos, derramar bebidas", "Pedir agua"]'::jsonb,1,'Slow service and offer food/water early.','Sirve más despacio y ofrece comida y agua pronto.','https://www.niaaa.nih.gov/alcohols-effects-health/alcohol-topics/alcohol-facts-and-statistics/understanding-binge-drinking'),
('all','bartender','bar','How do you cut someone off politely?','¿Cómo dejas de servirle a alguien con cortesía?','["Loudly in front of others", "Privately, calmly, no blame; offer water/food/ride; tell the manager", "Just ignore them"]'::jsonb,'["En voz alta frente a otros", "En privado, con calma, sin culpar; ofrecer agua, comida o transporte; avisar al gerente", "Ignorarlo"]'::jsonb,1,'Use ''I'' statements and stay firm.','Habla en primera persona y mantente firme.','general hospitality best practice'),
('all','bartender','bar','Can you serve someone who''s already obviously intoxicated?','¿Puedes servir a alguien visiblemente intoxicado?','["Yes, beer only", "Yes, if they pay cash", "No—it''s illegal in Minnesota"]'::jsonb,'["Sí, solo cerveza", "Sí, si paga en efectivo", "No, es ilegal en Minnesota"]'::jsonb,2,'Serving an obviously intoxicated person is prohibited.','Servir a una persona visiblemente intoxicada está prohibido.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','A guest of age orders for a friend who looks underage. You:','Un adulto pide para un amigo que parece menor. Tú:','["ID the friend too; refuse if under 21", "Serve both", "Serve only the adult''s drink, then don''t watch"]'::jsonb,'["Pedir identificación al amigo también; negar si es menor", "Servir a ambos", "Servir solo al adulto y no vigilar"]'::jsonb,0,'Watch for ''secondary'' purchases for minors.','Vigila compras para menores.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','Every comp or void should be:','Toda cortesía o anulación debe:','["Never recorded", "Done quietly", "Logged in the app with a reason and manager approval"]'::jsonb,'["No registrarse", "Hacerse en silencio", "Registrarse en la app con motivo y aprobación del gerente"]'::jsonb,2,'Accurate logs keep variance and pour cost honest.','Registros exactos mantienen honestos la variación y el costo.','general hospitality best practice'),
('all','bartender','bar','A standard pour helps with:','Una medida estándar ayuda con:','["Consistent drinks, accurate pour cost, responsible service", "Nothing", "Bigger tips only"]'::jsonb,'["Bebidas consistentes, costo exacto y servicio responsable", "Nada", "Solo propinas"]'::jsonb,0,'Use a jigger or measured pour.','Usa medidor (jigger) o medida exacta.','general hospitality best practice'),
('all','bartender','bar','You refuse service to a guest. You should also:','Le niegas el servicio a un huésped. También debes:','["Log the refusal and tell the manager", "Keep it secret", "Serve them at the end"]'::jsonb,'["Registrar la negativa y avisar al gerente", "Guardarlo en secreto", "Servirle al final"]'::jsonb,0,'Records protect you and the hotel.','Los registros te protegen a ti y al hotel.','general hospitality best practice'),
('all','bartender','bar','Opening the bar, first count:','Al abrir el bar, primer conteo:','["Starting bank and bottle counts in the app", "Guests", "Tips"]'::jsonb,'["Fondo de caja y conteo de botellas en la app", "Huéspedes", "Propinas"]'::jsonb,0,'Counts start the shift''s variance tracking.','Los conteos inician el control de variación del turno.','general hospitality best practice'),
('all','bartender','bar','Last call should be handled by:','El último llamado se maneja:','["Serving extra rounds", "Announcing clearly per posted hours and stopping on time", "Skipping it"]'::jsonb,'["Sirviendo rondas extra", "Anunciándolo claro según el horario y cerrando a tiempo", "Omitiéndolo"]'::jsonb,1,'Follow the hotel''s license hours.','Sigue el horario de la licencia del hotel.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','Broken glass near the ice bin. You:','Se rompió un vaso cerca del hielo. Tú:','["Keep serving", "Pick out the pieces", "Burn (melt/empty) the ice, clean, and sanitize"]'::jsonb,'["Seguir sirviendo", "Sacar los pedazos", "Desechar todo el hielo, limpiar y desinfectar"]'::jsonb,2,'You can''t see all glass in ice.','No se ve todo el vidrio en el hielo.','general hospitality best practice'),
('all','bartender','bar','Never scoop ice with:','Nunca saques hielo con:','["A scoop", "A glass", "A clean ice scoop with handle"]'::jsonb,'["Una pala", "Un vaso", "Una pala limpia con mango"]'::jsonb,1,'Glasses chip and break. Use a scoop.','Los vasos se rompen. Usa una pala.','https://www.fda.gov/food/fda-food-code/food-code-2022'),
('all','bartender','bar','A guest wants a drink to go to their room. You:','Un huésped quiere llevar una bebida a su habitación. Tú:','["Pour into a water bottle", "Follow the hotel''s license rules—ask the manager if unsure", "Always yes"]'::jsonb,'["Servirla en una botella de agua", "Seguir las reglas de la licencia del hotel; pregunta al gerente si dudas", "Siempre sí"]'::jsonb,1,'License rules vary; know your hotel''s.','Las reglas varían; conoce las del hotel.','https://dps.mn.gov/divisions/age'),
('all','bartender','bar','At close, the cash drop should be:','Al cerrar, el depósito de efectivo debe:','["Taken home", "Left in the drawer", "Counted, photographed in the app, and dropped per policy"]'::jsonb,'["Llevarse a casa", "Dejarse en la caja", "Contarse, fotografiarse en la app y depositarse según la política"]'::jsonb,2,'Over/short is tracked by the app.','La app registra sobrantes y faltantes.','general hospitality best practice'),
('all','management','management','A team member reports an injury. First thing you do?','Un empleado reporta una lesión. ¿Qué haces primero?','["Make sure they get care, then document", "Wait until next shift", "Ask if they''re sure"]'::jsonb,'["Asegurar atención y luego documentar", "Esperar al siguiente turno", "Preguntarle si está seguro"]'::jsonb,0,'Care first, then incident report.','Primero la atención, luego el reporte.','general hospitality best practice'),
('all','management','management','Under OSHA HazCom, employees must have:','Según HazCom de OSHA, los empleados deben tener:','["Access to SDS, labels, and training", "Nothing", "Only verbal warnings"]'::jsonb,'["Acceso a SDS, etiquetas y capacitación", "Nada", "Solo avisos verbales"]'::jsonb,0,'Train on chemicals they use.','Capacita sobre los químicos que usan.','https://www.osha.gov/hazcom'),
('all','management','management','The best way to give feedback is:','La mejor forma de dar retroalimentación es:','["Public criticism", "Once a year only", "Specific, timely, private for corrections"]'::jsonb,'["Crítica en público", "Solo una vez al año", "Específica, oportuna y en privado para correcciones"]'::jsonb,2,'Praise in public, correct in private.','Elogia en público, corrige en privado.','general hospitality best practice'),
('all','management','management','Service recovery best practice:','Buena práctica de recuperación del servicio:','["Offer max comps first", "Listen, apologize, fix, follow up, log it", "Deny"]'::jsonb,'["Ofrecer cortesías máximas primero", "Escuchar, disculparse, resolver, dar seguimiento y registrar", "Negar"]'::jsonb,1,'Log complaints to spot patterns.','Registra quejas para ver patrones.','general hospitality best practice'),
('all','management','management','Why track QOTD weak topics?','¿Por qué revisar los temas débiles del QOTD?','["To punish staff", "No reason", "To target short refresher trainings"]'::jsonb,'["Para castigar", "Sin razón", "Para hacer capacitaciones cortas enfocadas"]'::jsonb,2,'Use analytics to coach, not to penalize.','Usa los datos para entrenar, no para castigar.','general hospitality best practice'),
('all','management','management','A guest tells you a staff member was rude. You:','Un huésped dice que un empleado fue grosero. Tú:','["Ignore", "Thank them, apologize, investigate facts, coach privately", "Fire on the spot"]'::jsonb,'["Ignorar", "Agradecer, disculparte, investigar y entrenar en privado", "Despedir en el momento"]'::jsonb,1,'Get both sides before acting.','Escucha ambas partes antes de actuar.','general hospitality best practice'),
('all','management','management','Bloodborne pathogen training should be given to:','La capacitación de patógenos debe darse a:','["Only GMs", "Staff with reasonably anticipated exposure (e.g., housekeeping, maintenance)", "No one"]'::jsonb,'["Solo gerentes", "Personal con exposición razonablemente prevista (p. ej., limpieza, mantenimiento)", "Nadie"]'::jsonb,1,'Annual training is required for exposed workers.','Se requiere capacitación anual para los expuestos.','https://www.osha.gov/bloodborne-pathogens'),
('all','management','management','Lost master key. Right response?','Se perdió una llave maestra. ¿Respuesta correcta?','["Wait to see if it turns up", "Make a copy", "Document it and re-key/deactivate it right away"]'::jsonb,'["Esperar a que aparezca", "Hacer copia", "Documentarlo y desactivarla o cambiar cerraduras de inmediato"]'::jsonb,2,'Deactivate electronic master keys immediately.','Desactiva las llaves electrónicas de inmediato.','general hospitality best practice'),
('all','management','management','Labor planning should flex based on:','La planificación de personal debe ajustarse según:','["Last year''s schedule only", "Occupancy and standards", "Gut feel only"]'::jsonb,'["Solo el horario del año pasado", "Ocupación y estándares", "Solo intuición"]'::jsonb,1,'Use the portal''s labor plan.','Usa el plan de personal del portal.','general hospitality best practice'),
('all','management','management','Signs of human trafficking reported by staff should be:','Las señales de trata reportadas por el personal deben:','["Ignored", "Handled by confronting the guest", "Taken seriously and reported to authorities; don''t confront"]'::jsonb,'["Ignorarse", "Manejarse confrontando al huésped", "Tomarse en serio y reportarse a las autoridades; no confrontar"]'::jsonb,2,'DHS Blue Campaign has hotel resources.','La campaña Blue Campaign del DHS tiene recursos para hoteles.','https://www.dhs.gov/blue-campaign'),
('all','management','management','Approving your own points or comps is:','Aprobar tus propios puntos o cortesías es:','["Not allowed—separation of duties", "Encouraged", "Fine"]'::jsonb,'["No permitido; separación de funciones", "Recomendado", "Correcto"]'::jsonb,0,'The portal blocks self-approval.','El portal bloquea la autoaprobación.','general hospitality best practice'),
('all','management','management','Best way to raise loyalty enrollments?','¿Mejor forma de aumentar inscripciones de lealtad?','["Only yearly reminders", "Daily goals, quick coaching, recognition", "Pressure guests"]'::jsonb,'["Solo recordatorios anuales", "Metas diarias, entrenamiento rápido y reconocimiento", "Presionar a huéspedes"]'::jsonb,1,'Points for enrollments help too.','Los puntos por inscripción también ayudan.','general hospitality best practice'),
('all','management','management','Bar variance is high this week. First check:','La variación del bar es alta esta semana. Primero revisa:','["Ignore it", "Counts, comps/voids logs, receiving, and pours", "Fire the bartender"]'::jsonb,'["Ignorarlo", "Conteos, registros de cortesías y anulaciones, recepción y medidas", "Despedir al bartender"]'::jsonb,1,'Most variance comes from process gaps.','La mayoría de la variación viene de fallas en el proceso.','general hospitality best practice'),
('all','management','management','A new hire''s first week should include:','La primera semana de un nuevo empleado debe incluir:','["Nothing", "Only paperwork", "Safety, brand standards, and a buddy"]'::jsonb,'["Nada", "Solo papeleo", "Seguridad, estándares de marca y un compañero guía"]'::jsonb,2,'Good onboarding reduces turnover.','Una buena inducción reduce la rotación.','general hospitality best practice'),
('IHG','driver','loyalty','A shuttle guest asks if Holiday Inn Express has a rewards program. You say:','Un huésped del shuttle pregunta si Holiday Inn Express tiene programa de recompensas. Dices:','["Yes, IHG One Rewards—free to join at the front desk", "Only for business travelers", "No"]'::jsonb,'["Sí, IHG One Rewards; es gratis inscribirse en recepción", "Solo para viajeros de negocios", "No"]'::jsonb,0,'Every guest touchpoint is an enrollment chance.','Cada contacto con el huésped es una oportunidad de inscribir.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('IHG','housekeeping','loyalty','Which IHG tiers get early check-in (subject to availability)?','¿Qué niveles de IHG tienen entrada anticipada (según disponibilidad)?','["Platinum and Diamond", "All members", "Silver only"]'::jsonb,'["Platinum y Diamond", "Todos los socios", "Solo Silver"]'::jsonb,0,'Early check-in is listed for Platinum and Diamond.','La entrada anticipada aparece para Platinum y Diamond.','https://www.ihg.com/onerewards/content/us/en/tier-benefits'),
('Hilton','housekeeping','loyalty','Diamond Reserve members get guaranteed late checkout until:','Los socios Diamond Reserve tienen salida tardía garantizada hasta:','["12 PM", "4 PM", "2 PM"]'::jsonb,'["12 p. m.", "4 p. m.", "2 p. m."]'::jsonb,1,'Diamond Reserve: guaranteed 4 PM late checkout.','Diamond Reserve: salida tardía garantizada a las 4 p. m.','https://www.hilton.com/en/help-center/hilton-honors-benefits/tiers-and-benefits/'),
('Marriott','all','loyalty','Which Marriott Bonvoy tier needs 75 nights per year?','¿Qué nivel de Marriott Bonvoy requiere 75 noches al año?','["Ambassador Elite", "Platinum Elite", "Titanium Elite"]'::jsonb,'["Ambassador Elite", "Platinum Elite", "Titanium Elite"]'::jsonb,2,'Titanium: 75 nights.','Titanium: 75 noches.','https://www.marriott.com/loyalty.mi')
